/// Extract host:port from a SocketAddress synthetic object.
///
/// Handles three layouts:
/// - **CratonVM synthetic 2-field** (legacy probes): field 0 = host string,
///   field 1 = port int.
/// - **Real-JDK 25 `InetSocketAddress`**: one `holder` field of type
///   `InetSocketAddressHolder` with `{hostname, addr, port}`. We follow the
///   `holder` chain and read `port` + `hostname` by name.
/// - **Unknown / unresolved**: fall back to `"0.0.0.0:0"` so the listener
///   binds to the wildcard ephemeral port (matches HotSpot behaviour for a
///   `null` address). Returning `"127.0.0.1:0"` here was wrong — Tomcat's
///   server connectors expect to bind on the all-interfaces wildcard, and a
///   loopback-only listener fails the regression probe later when something
///   tries to connect from outside.
fn p98_extract_socket_addr(ctx: &mut dyn NativeContext, addr: Value) -> String {
    let a = match addr {
        Value::Object(Some(a)) => a,
        _ => return "0.0.0.0:0".to_string(),
    };

    // Real-JDK path first: probe for `holder` field by name. If present, the
    // host + port live one level deeper via `holder.hostname` /
    // `holder.addr.hostName` / `holder.port`. This is the layout JDK 25 ships
    // and Tomcat / Netty / Jetty all hand us.
    match ctx.get_field_by_name(a, "holder") {
        Value::Object(Some(h)) => {
            let port = match ctx.get_field_by_name(h, "port") {
                Value::Int(p) => p,
                _ => 0,
            };
            // Prefer holder.hostname when set; fall back to holder.addr's
            // host string. If neither resolves, use the wildcard so the
            // bind succeeds on all interfaces.
            let host = match ctx.get_field_by_name(h, "hostname") {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let host = if !host.is_empty() {
                host
            } else if let Value::Object(Some(ia)) = ctx.get_field_by_name(h, "addr") {
                // InetAddress.holder.hostName / InetAddress.holder.address fallback.
                match ctx.get_field_by_name(ia, "holder") {
                    Value::Object(Some(iah)) => match ctx.get_field_by_name(iah, "hostName") {
                        Value::Object(Some(s)) => {
                            ctx.read_string(s).unwrap_or_else(|| "0.0.0.0".into())
                        }
                        _ => "0.0.0.0".into(),
                    },
                    _ => "0.0.0.0".into(),
                }
            } else {
                "0.0.0.0".into()
            };
            return format!("{}:{}", host, port);
        }
        _ => {}
    }

    // Synthetic 2-field fallback (the legacy probe layout).
    let host = match ctx.get_field(a, 0) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "0.0.0.0".to_string()),
        _ => "0.0.0.0".to_string(),
    };
    let port = ctx.get_field(a, 1).as_int().unwrap_or(0);
    format!("{}:{}", host, port)
}

fn p98_selector_select(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    p98_do_select(ctx, this)
}

/// Blocking select: loops polling with 1ms sleeps until ready_count > 0 or wakeup flag is set.
fn p98_blocking_select(
    ctx: &mut dyn NativeContext,
    selector: ObjectRef,
    timeout_ms: i64,
) -> MethodCallResult {
    // Clear wakeup flag at start
    ctx.set_field(selector, 3, Value::Int(0));

    let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms as u64);
    loop {
        let result = p98_do_select(ctx, selector)?;
        let count = result.as_ref().and_then(|v| v.as_int()).unwrap_or(0);
        if count > 0 {
            return Ok(result);
        }
        // Check wakeup flag
        if ctx.get_field(selector, 3).as_int().unwrap_or(0) != 0 {
            ctx.set_field(selector, 3, Value::Int(0)); // consume wakeup
            return Ok(Some(Value::Int(0)));
        }
        // Check timeout
        if std::time::Instant::now() >= deadline {
            return Ok(Some(Value::Int(0)));
        }
        std::thread::sleep(std::time::Duration::from_millis(1));
    }
}

/// Single poll pass across all registered keys. Clears readyOps before polling.
fn p98_do_select(ctx: &mut dyn NativeContext, selector: ObjectRef) -> MethodCallResult {
    let key_count = ctx.get_field(selector, 2).as_int().unwrap_or(0) as usize;
    let mut ready_count = 0i32;
    if let Value::Object(Some(ka)) = ctx.get_field(selector, 1) {
        for i in 0..key_count {
            if let Value::Object(Some(key)) = ctx.get_array_element(ka, i) {
                // Clear readyOps at start of each poll cycle
                ctx.set_field(key, 3, Value::Int(0));
                let interest = ctx.get_field(key, 2).as_int().unwrap_or(0);
                let fd = if let Value::Object(Some(ch)) = ctx.get_field(key, 0) {
                    let fd3 = ctx.get_field(ch, 3).as_int().unwrap_or(-1);
                    if fd3 >= 0 {
                        fd3
                    } else {
                        ctx.get_field(ch, 2).as_int().unwrap_or(-1)
                    }
                } else {
                    -1
                };
                if fd >= 0 {
                    let (readable, writable) = ctx.fd_table().poll_ready(fd as u32);
                    let mut ready = 0;
                    if readable && (interest & 1 != 0) {
                        ready |= 1;
                    } // OP_READ
                    if writable && (interest & 4 != 0) {
                        ready |= 4;
                    } // OP_WRITE
                    if writable && (interest & 8 != 0) {
                        ready |= 8;
                    } // OP_CONNECT
                    if readable && (interest & 16 != 0) {
                        ready |= 16;
                    } // OP_ACCEPT
                    ctx.set_field(key, 3, Value::Int(ready));
                    if ready != 0 {
                        ready_count += 1;
                    }
                }
            }
        }
    }
    Ok(Some(Value::Int(ready_count)))
}

// =============================================================================
// GZIP / Zip streams — real flate2 compression/decompression
// GZIPInputStream = 2-field (decompressed_data=0 byte[], position=1 Int)
// GZIPOutputStream = 2-field (accumulated_data=0 byte[], count=1 Int)
// ZipInputStream = 2-field (in=0, currentEntry=1)
// ZipOutputStream = 2-field (out=0, currentEntry=1)
// =============================================================================

/// Default cap on the total number of inflated bytes a single GZIP/Zip input
/// stream may produce (256 MiB). Overridable at runtime via
/// `CRATONVM_MAX_INFLATED_BYTES` (decimal byte count; `0` disables the cap).
///
/// FIX (finding 3): these synthetic streams eagerly inflate the WHOLE input in
/// `<init>`. Without a bound, a few-KB "zip/gzip bomb" can inflate to gigabytes
/// and exhaust the heap before any Java code runs. The cap turns that into a
/// loud `IOException` instead of an OOM crash.
const GZIP_DEFAULT_MAX_INFLATED: u64 = 256 * 1024 * 1024;

/// Resolve the configured max inflated-size cap. Returns `None` when the cap is
/// explicitly disabled (`CRATONVM_MAX_INFLATED_BYTES=0`).
fn gzip_max_inflated_bytes() -> Option<u64> {
    match std::env::var("CRATONVM_MAX_INFLATED_BYTES") {
        Ok(s) => match s.trim().parse::<u64>() {
            Ok(0) => None, // explicitly disabled
            Ok(n) => Some(n),
            Err(_) => Some(GZIP_DEFAULT_MAX_INFLATED),
        },
        Err(_) => Some(GZIP_DEFAULT_MAX_INFLATED),
    }
}

/// Inflate `reader` fully into a `Vec<u8>`, refusing to exceed `cap` bytes.
///
/// Reads in chunks so memory grows incrementally; as soon as the running total
/// would exceed `cap` we stop and return `Err` (compression-bomb defense). When
/// `cap` is `None` the read is unbounded (legacy behavior, opt-in only).
fn inflate_bounded<R: std::io::Read>(
    mut reader: R,
    cap: Option<u64>,
) -> Result<Vec<u8>, std::io::Error> {
    use std::io::Read;
    let mut out: Vec<u8> = Vec::new();
    let mut chunk = [0u8; 64 * 1024];
    loop {
        let n = reader.read(&mut chunk)?;
        if n == 0 {
            break;
        }
        if let Some(limit) = cap {
            if out.len() as u64 + n as u64 > limit {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    format!(
                        "inflated size exceeds CRATONVM_MAX_INFLATED_BYTES cap ({limit} bytes) \
                         — possible compression bomb"
                    ),
                ));
            }
        }
        out.extend_from_slice(&chunk[..n]);
    }
    Ok(out)
}

/// Drain a Java `InputStream` fully into a host `Vec<u8>`.
///
/// PERF: the GZIP/Zip `<init>` natives previously slurped the underlying stream
/// ONE BYTE AT A TIME via `read()I`, paying a full virtual-dispatch + `Value`
/// box per byte (catastrophic for multi-MB archives). This reads in 64 KiB
/// chunks through the bulk `read([B,I,I)I` virtual instead, copying each chunk
/// out with the `read_byte_array_into` memcpy intrinsic. A single reusable Java
/// `byte[]` buffer is allocated for the whole drain.
///
/// Behavior is identical to the old per-byte loop ("read until EOF"): if the
/// bulk read is unsupported (errors / returns a non-int) or returns 0 with a
/// non-zero request length (a misbehaving stream that would otherwise spin), we
/// fall back to the per-byte `read()I` loop for the remainder, so no input is
/// ever lost.
fn drain_input_stream_bulk(ctx: &mut dyn NativeContext, is_ref: ObjectRef) -> Vec<u8> {
    const CHUNK: usize = 64 * 1024;
    let mut out: Vec<u8> = Vec::new();
    // Pin across the read callbacks below — a moving young GC there would
    // relocate the stream/buffer (native stale-local family).
    let is_pin = ctx.pin_native_root(is_ref);
    let buf = ctx.new_array(cratonvm_types::ArrayElementType::Byte, CHUNK);
    let buf_pin = ctx.pin_native_root(buf);
    // Heap-allocated scratch (not a 64 KiB stack array) to keep native-call
    // frames shallow; reused across every chunk.
    let mut scratch = vec![0u8; CHUNK];
    loop {
        let is_cur = ctx.read_native_pin(is_pin, is_ref);
        let buf_cur = ctx.read_native_pin(buf_pin, buf);
        let res = ctx.invoke_virtual(
            is_cur,
            "read",
            "([BII)I",
            &[
                Value::Object(Some(buf_cur)),
                Value::Int(0),
                Value::Int(CHUNK as i32),
            ],
        );
        match res {
            Ok(Some(Value::Int(n))) if n > 0 => {
                let n = n as usize;
                let buf_cur = ctx.read_native_pin(buf_pin, buf);
                let copied = ctx.read_byte_array_into(buf_cur, 0, &mut scratch[..n]);
                out.extend_from_slice(&scratch[..copied]);
                if copied < n {
                    // Defensive: array shorter than reported — stop to avoid a
                    // bogus read; matches the old loop's "break on anomaly".
                    break;
                }
            }
            Ok(Some(Value::Int(n))) if n < 0 => break, // EOF
            // n == 0 (shouldn't happen for len>0) or bulk read unsupported:
            // finish the drain via the per-byte path so nothing is dropped.
            _ => {
                let is_cur = ctx.read_native_pin(is_pin, is_ref);
                drain_input_stream_per_byte(ctx, is_cur, &mut out);
                break;
            }
        }
    }
    ctx.unpin_native_roots(is_pin);
    out
}

/// Per-byte drain fallback (the original `read()I` loop). Appends to `out`.
fn drain_input_stream_per_byte(ctx: &mut dyn NativeContext, is_ref: ObjectRef, out: &mut Vec<u8>) {
    // Pin across the read callbacks below — a moving young GC there would
    // relocate the stream (native stale-local family).
    let is_pin = ctx.pin_native_root(is_ref);
    loop {
        let is_cur = ctx.read_native_pin(is_pin, is_ref);
        match ctx.invoke_virtual(is_cur, "read", "()I", &[]) {
            Ok(Some(Value::Int(b))) if b >= 0 => out.push(b as u8),
            _ => break,
        }
    }
    ctx.unpin_native_roots(is_pin);
}

pub(crate) fn register_p58_gzip_streams(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // Real-JDK GZIPInputStream must retain its bytecode implementation: it
    // initializes and drives the zlib state through zip_real's private
    // Inflater natives.  Synthetic-layout replacements here corrupt real JDK
    // resource streams, so only the GZIPOutputStream bridge remains below.

    // GZIPOutputStream — accumulates data in field 0/1, compresses on finish
    let go = "java/util/zip/GZIPOutputStream";
    r.register(go, "<init>", "(Ljava/io/OutputStream;)V", p58_gzip_out_init);
    r.register(go, "write", "(I)V", p58_gzip_out_write);
    r.register(go, "write", "([BII)V", p58_gzip_out_write_bytes);
    r.register(go, "finish", "()V", p58_gzip_out_finish);
    r.register(go, "flush", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Flush underlying stream
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 2) {
            let _ = ctx.invoke_virtual(underlying, "flush", "()V", &[]);
        }
        Ok(None)
    });
    r.register(go, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Finish compression if not already done (count >= 0 means not finished)
        let count = ctx.get_field(this, 1).as_int().unwrap_or(0);
        if count >= 0 {
            p58_gzip_out_finish(ctx, args)?;
        }
        // Close underlying stream
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 2) {
            let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
        }
        Ok(None)
    });

    // ZipInputStream = 5-field (underlying=0, entry_names=1, entry_data=2, current_index=3, read_pos=4)
    let zi = "java/util/zip/ZipInputStream";
    r.register(zi, "<init>", "(Ljava/io/InputStream;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        ctx.set_field(this, 3, Value::Int(-1)); // before first entry
        ctx.set_field(this, 4, Value::Int(0));

        // Eagerly read all bytes from the underlying InputStream.
        // PERF: bulk-drain via read([B,I,I)I instead of a per-byte read()I loop.
        let all_bytes = match args.get(1) {
            Some(Value::Object(Some(is_ref))) => drain_input_stream_bulk(ctx, *is_ref),
            _ => Vec::new(),
        };

        // Parse with zip crate
        if !all_bytes.is_empty() {
            let cursor = std::io::Cursor::new(&all_bytes);
            if let Ok(mut archive) = zip::ZipArchive::new(cursor) {
                let count = archive.len();
                // Pin across the per-entry string/array allocs below — a
                // moving young GC there would relocate `this` and the fresh
                // arrays (native stale-local family).
                let this_pin = ctx.pin_native_root(this);
                let names_arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, count);
                let names_pin = ctx.pin_native_root(names_arr);
                let data_arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, count);
                let data_pin = ctx.pin_native_root(data_arr);
                // Bound the CUMULATIVE inflated size across all entries so a zip
                // bomb (many/large entries) throws instead of exhausting the heap
                // (finding 3). `remaining` tracks the budget left for this archive.
                let cap = gzip_max_inflated_bytes();
                let mut remaining: Option<u64> = cap;
                for i in 0..count {
                    if let Ok(entry) = archive.by_index(i) {
                        let name = ctx.create_string(entry.name());
                        let names_arr = ctx.read_native_pin(names_pin, names_arr);
                        ctx.set_array_element(names_arr, i, Value::Object(Some(name)));
                        let entry_bytes = match inflate_bounded(entry, remaining) {
                            Ok(b) => b,
                            Err(_) => {
                                ctx.unpin_native_roots(this_pin);
                                // Cap exceeded mid-archive → fail loud.
                                return Err(RuntimeError::IOException {
                                    message: format!(
                                        "ZipInputStream: inflated size exceeds \
                                         CRATONVM_MAX_INFLATED_BYTES cap ({} bytes) \
                                         — possible compression bomb",
                                        cap.unwrap_or(0)
                                    ),
                                }
                                .into());
                            }
                        };
                        if let Some(rem) = remaining.as_mut() {
                            *rem = rem.saturating_sub(entry_bytes.len() as u64);
                        }
                        let byte_arr = ctx
                            .new_array(cratonvm_types::ArrayElementType::Byte, entry_bytes.len());
                        // PERF: bulk memcpy the inflated entry instead of a
                        // per-element set_array_element loop.
                        ctx.write_byte_array_from(byte_arr, 0, &entry_bytes);
                        let data_arr = ctx.read_native_pin(data_pin, data_arr);
                        ctx.set_array_element(data_arr, i, Value::Object(Some(byte_arr)));
                    }
                }
                let this = ctx.read_native_pin(this_pin, this);
                let names_arr = ctx.read_native_pin(names_pin, names_arr);
                let data_arr = ctx.read_native_pin(data_pin, data_arr);
                ctx.set_field(this, 1, Value::Object(Some(names_arr)));
                ctx.set_field(this, 2, Value::Object(Some(data_arr)));
                ctx.unpin_native_roots(this_pin);
            } else {
                ctx.set_field(this, 1, Value::Object(None));
                ctx.set_field(this, 2, Value::Object(None));
            }
        } else {
            ctx.set_field(this, 1, Value::Object(None));
            ctx.set_field(this, 2, Value::Object(None));
        }
        Ok(None)
    });
    r.register(
        zi,
        "getNextEntry",
        "()Ljava/util/zip/ZipEntry;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let idx = ctx.get_field(this, 3).as_int().unwrap_or(-1) + 1;
            ctx.set_field(this, 3, Value::Int(idx));
            ctx.set_field(this, 4, Value::Int(0)); // reset read position

            // Check if we have entries
            let names_arr = match ctx.get_field(this, 1) {
                Value::Object(Some(a)) => a,
                _ => return Ok(Some(Value::Object(None))),
            };
            let count = ctx.array_length(names_arr);
            if idx < 0 || (idx as usize) >= count {
                return Ok(Some(Value::Object(None)));
            }
            // Create ZipEntry with name
            let name_val = ctx.get_array_element(names_arr, idx as usize);
            // Pin across the ZipEntry alloc below — a moving young GC there
            // would relocate them (native stale-local family).
            let name_pin = pinned_object_value(ctx, name_val);
            let this_pin = ctx.pin_native_root(this);
            let ze = alloc_concurrent_synthetic(ctx, "java/util/zip/ZipEntry", 2);
            let name_val = read_pinned_object_value(ctx, name_pin, name_val);
            let this = ctx.read_native_pin(this_pin, this);
            if let Some((h, _)) = name_pin {
                ctx.unpin_native_roots(h);
            } else {
                ctx.unpin_native_roots(this_pin);
            }
            ctx.set_field(ze, 0, name_val); // name
                                            // Set size from data array
            if let Value::Object(Some(data_arr)) = ctx.get_field(this, 2) {
                if let Value::Object(Some(entry_data)) =
                    ctx.get_array_element(data_arr, idx as usize)
                {
                    let size = ctx.array_length(entry_data);
                    ctx.set_field(ze, 1, Value::Int(size as i32));
                }
            }
            Ok(Some(Value::Object(Some(ze))))
        },
    );
    r.register(zi, "closeEntry", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 4, Value::Int(0));
        Ok(None)
    });
    r.register(zi, "read", "([BII)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = ctx.get_field(this, 3).as_int().unwrap_or(-1);
        if idx < 0 {
            return Ok(Some(Value::Int(-1)));
        }

        let data_arr = match ctx.get_field(this, 2) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Int(-1))),
        };
        let entry_data = match ctx.get_array_element(data_arr, idx as usize) {
            Value::Object(Some(a)) => a,
            _ => return Ok(Some(Value::Int(-1))),
        };
        let entry_len = ctx.array_length(entry_data);
        let pos = ctx.get_field(this, 4).as_int().unwrap_or(0) as usize;
        if pos >= entry_len {
            return Ok(Some(Value::Int(-1)));
        }

        let dst = match args.get(1) {
            Some(Value::Object(Some(a))) => *a,
            _ => return Ok(Some(Value::Int(-1))),
        };
        let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let len = args.get(3).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let available = entry_len - pos;
        let to_read = len.min(available);

        for i in 0..to_read {
            let b = ctx.get_array_element(entry_data, pos + i);
            ctx.set_array_element(dst, off + i, b);
        }
        ctx.set_field(this, 4, Value::Int((pos + to_read) as i32));
        Ok(Some(Value::Int(to_read as i32)))
    });
    r.register(zi, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Propagate to the wrapped underlying InputStream (field 0), same
        // as real `ZipInputStream.close()` → `InflaterInputStream.close()`
        // → `FilterInputStream.close()` → `in.close()`. `<init>` eagerly
        // drains `this` into in-memory byte arrays, so nothing here itself
        // holds an OS handle open — but the underlying stream might (e.g. a
        // caller-supplied `Closeable`-backed stream). This synthetic path
        // only runs under `--synthetic-jdk` (real-JDK boot dispatches to the
        // genuine `ZipInputStream`/`InflaterInputStream` bytecode instead,
        // per `check_override` in vm_exec.rs) — kept correct for parity with
        // that mode rather than leaving an unconditional no-op here.
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
        }
        ctx.set_field(this, 1, Value::Object(None));
        ctx.set_field(this, 2, Value::Object(None));
        Ok(None)
    });

    // ZipOutputStream = 5-field (underlying=0, entry_names=1, entry_data_list=2,
    //                            current_entry_name=3, current_entry_buf=4)
    let zo = "java/util/zip/ZipOutputStream";
    r.register(zo, "<init>", "(Ljava/io/OutputStream;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        // Initialize empty entry lists (using arrays as dynamic lists with a count sentinel)
        let names = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 64);
        let datas = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 64);
        ctx.set_field(this, 1, Value::Object(Some(names)));
        ctx.set_field(this, 2, Value::Object(Some(datas)));
        ctx.set_field(this, 3, Value::Object(None)); // no current entry
        ctx.set_field(this, 4, Value::Int(0)); // entry count
        Ok(None)
    });
    r.register(
        zo,
        "putNextEntry",
        "(Ljava/util/zip/ZipEntry;)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            // Read entry name from ZipEntry (field 0)
            let entry_name = match args.get(1) {
                Some(Value::Object(Some(ze))) => ctx.get_field(*ze, 0),
                _ => Value::Object(None),
            };
            ctx.set_field(this, 3, entry_name);
            Ok(None)
        },
    );
    // Internal accumulator for current entry data.
    r.register(zo, "write", "([BII)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Some(Value::Object(Some(src))) = args.get(1) {
            // Validate signed off/len against the array length BEFORE casting to
            // usize. A negative len would sign-extend into a huge usize and
            // abort `Vec::with_capacity`; OutputStream.write([BII) contractually
            // throws IndexOutOfBoundsException on bad bounds.
            let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
            let len = args.get(3).and_then(|v| v.as_int()).unwrap_or(0);
            let arr_len = ctx.array_length(*src) as i64;
            if off < 0 || len < 0 || (off as i64) + (len as i64) > arr_len {
                return Err(RuntimeError::ArrayIndexOutOfBoundsException {
                    index: if off < 0 { off } else { off.wrapping_add(len) },
                }
                .into());
            }
            let off = off as usize;
            let len = len as usize;
            let mut bytes = Vec::with_capacity(len);
            for i in 0..len {
                if let Value::Int(b) = ctx.get_array_element(*src, off + i) {
                    bytes.push(b as u8);
                }
            }
            // Accumulate in a Rust-side buffer via a temporary byte array
            // Read existing accumulated bytes for this entry, append new ones
            zo_append_entry_data(ctx, this, &bytes);
        }
        Ok(None)
    });
    // write(int) and write([B) MUST be overridden on ZipOutputStream too:
    // DataOutputStream.writeBytes (used by Manifest.write) emits the data one
    // byte at a time via out.write(int). Without a ZipOutputStream-level
    // override that path falls through to DeflaterOutputStream.write(int) — a
    // no-op here — silently dropping every byte (e.g. an empty MANIFEST.MF when
    // building a JAR via `new JarOutputStream(out, manifest)`).
    r.register(zo, "write", "(I)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let b = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) as u8;
        zo_append_entry_data(ctx, this, &[b]);
        Ok(None)
    });
    r.register(zo, "write", "([B)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Some(Value::Object(Some(src))) = args.get(1) {
            let len = ctx.array_length(*src);
            let mut bytes = Vec::with_capacity(len);
            for i in 0..len {
                if let Value::Int(b) = ctx.get_array_element(*src, i) {
                    bytes.push(b as u8);
                }
            }
            zo_append_entry_data(ctx, this, &bytes);
        }
        Ok(None)
    });
    r.register(zo, "closeEntry", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        zo_finalize_current_entry(ctx, this);
        Ok(None)
    });
    r.register(zo, "finish", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        // Finalize any open entry
        zo_finalize_current_entry(ctx, this);
        // Build zip and write to underlying stream
        zo_write_zip(ctx, this)?;
        Ok(None)
    });
    r.register(zo, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        zo_finalize_current_entry(ctx, this);
        zo_write_zip(ctx, this)?;
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
        }
        Ok(None)
    });

    // ZipEntry methods
    let ze = "java/util/zip/ZipEntry";
    r.register(ze, "<init>", "(Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
        ctx.set_field(this, 1, Value::Int(0));
        Ok(None)
    });
    r.register(ze, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ze, "getSize", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let size = ctx.get_field(this, 1).as_int().unwrap_or(0);
        Ok(Some(Value::Long(size as i64)))
    });
    r.register(ze, "isDirectory", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let is_dir = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => {
                let name = ctx.read_string(s).unwrap_or_default();
                name.ends_with('/')
            }
            _ => false,
        };
        Ok(Some(Value::Int(if is_dir { 1 } else { 0 })))
    });

    // InflaterInputStream / DeflaterOutputStream (abstract bases)
    r.register(
        "java/util/zip/InflaterInputStream",
        "read",
        "()I",
        |_ctx, _args| Ok(Some(Value::Int(-1))),
    );
    r.register(
        "java/util/zip/InflaterInputStream",
        "read",
        "([BII)I",
        |_ctx, _args| Ok(Some(Value::Int(-1))),
    );
    r.register(
        "java/util/zip/InflaterInputStream",
        "available",
        "()I",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    // `InflaterInputStream.close()` — NOT a blanket no-op. Real bytecode is
    // `if (!closed) { if (usesDefaultInflater) inf.end(); in.close(); closed
    // = true; }`; mirror it via by-name field access (real-layout objects,
    // not a synthetic fixed-slot convention).
    //
    // NOTE: empirically this native is NOT reached under real-JDK-boot mode
    // (the default) for concrete subclasses like Spring Boot loader's
    // `ZipInflaterInputStream` — the interpreter correctly prefers real
    // `InflaterInputStream.close()` bytecode there (confirmed via a
    // standalone repro: closing a 3-arg-constructed `InflaterInputStream`
    // wrapping a tracing stream correctly reached the tracing stream's
    // `close()` both with and without this native registered). The actual
    // cause of the Spring Boot `SecurityInfoTests`/`NestedJarFileTests`
    // file-handle leak was a DIFFERENT, more impactful bug — see the
    // `DataInputStream`/`BufferedInputStream` `"close"` registrations in
    // `native-builtins/src/classloader.rs`. This fix is kept regardless:
    // it's still correct, and matters for `--synthetic-jdk` mode (no real
    // bytecode to fall back to) or if dispatch precedence ever changes.
    r.register(
        "java/util/zip/InflaterInputStream",
        "close",
        "()V",
        |ctx, args| {
            eprintln!("[IIS_CLOSE_DBG] native InflaterInputStream.close invoked");
            let this = obj_arg(args, 0)?;
            if matches!(ctx.get_field_by_name(this, "closed"), Value::Int(1)) {
                return Ok(None);
            }
            if matches!(
                ctx.get_field_by_name(this, "usesDefaultInflater"),
                Value::Int(1)
            ) {
                if let Value::Object(Some(inf)) = ctx.get_field_by_name(this, "inf") {
                    let _ = ctx.invoke_virtual(inf, "end", "()V", &[]);
                }
            }
            if let Value::Object(Some(underlying)) = ctx.get_field_by_name(this, "in") {
                let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
            }
            ctx.set_field_by_name(this, "closed", Value::Int(1));
            Ok(None)
        },
    );
    r.register(
        "java/util/zip/DeflaterOutputStream",
        "write",
        "(I)V",
        native_noop_with_this,
    );
    r.register(
        "java/util/zip/DeflaterOutputStream",
        "write",
        "([BII)V",
        native_noop_with_this,
    );
    r.register(
        "java/util/zip/DeflaterOutputStream",
        "finish",
        "()V",
        native_noop_with_this,
    );
    r.register(
        "java/util/zip/DeflaterOutputStream",
        "flush",
        "()V",
        native_noop_with_this,
    );
    r.register(
        "java/util/zip/DeflaterOutputStream",
        "close",
        "()V",
        native_noop_with_this,
    );
    r.set_category(__prev_cat);
}

// GZIPInputStream: field 0=decompressed byte[], field 1=read position (Int)
// Reads all compressed data from underlying stream, decompresses with flate2, stores result.
fn p58_gzip_in_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let input_stream = args.get(1).copied().unwrap_or(Value::Object(None));
    // Read all bytes from underlying stream eagerly.  Resource streams are
    // frequently `ByteArrayInputStream`s backed by jar entries; use the scalar
    // path here until the generic bulk virtual-dispatch path can preserve each
    // compressed byte under all real-JDK stream subclasses.
    let mut compressed = Vec::new();
    if let Value::Object(Some(is)) = input_stream {
        drain_input_stream_per_byte(ctx, is, &mut compressed);
    }
    // Decompress with flate2 GzDecoder, bounded by the inflated-size cap so a
    // gzip bomb throws an IOException instead of exhausting the heap (finding 3).
    let decompressed = if !compressed.is_empty() {
        use flate2::read::GzDecoder;
        let decoder = GzDecoder::new(&compressed[..]);
        let cap = gzip_max_inflated_bytes();
        match inflate_bounded(decoder, cap) {
            Ok(buf) => buf,
            Err(e)
                if e.kind() == std::io::ErrorKind::InvalidData
                    && e.to_string().contains("compression bomb") =>
            {
                // Cap exceeded: fail loud rather than OOM.
                return Err(RuntimeError::IOException {
                    message: format!("GZIPInputStream: {e}"),
                }
                .into());
            }
            // Genuinely-not-gzip input keeps the lenient raw-passthrough behavior.
            Err(_) => compressed,
        }
    } else {
        Vec::new()
    };
    let arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, decompressed.len());
    // PERF: bulk memcpy the decompressed payload instead of a per-element loop.
    ctx.write_byte_array_from(arr, 0, &decompressed);
    ctx.set_field(this, 0, Value::Object(Some(arr))); // decompressed data
    ctx.set_field(this, 1, Value::Int(0)); // position
    Ok(None)
}

fn p58_gzip_in_read(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = ctx.get_field(this, 1).as_int().unwrap_or(0) as usize;
    if let Value::Object(Some(data)) = ctx.get_field(this, 0) {
        let len = ctx.array_length(data);
        if pos >= len {
            return Ok(Some(Value::Int(-1)));
        }
        let val = ctx.get_array_element(data, pos);
        ctx.set_field(this, 1, Value::Int((pos + 1) as i32));
        if let Value::Int(b) = val {
            Ok(Some(Value::Int(b & 0xFF)))
        } else {
            Ok(Some(Value::Int(-1)))
        }
    } else {
        Ok(Some(Value::Int(-1)))
    }
}

fn p58_gzip_in_read_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = ctx.get_field(this, 1).as_int().unwrap_or(0) as usize;
    let buf = obj_arg(args, 1)?;
    let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0) as usize;
    let len = args.get(3).and_then(|v| v.as_int()).unwrap_or(0) as usize;
    if let Value::Object(Some(data)) = ctx.get_field(this, 0) {
        let data_len = ctx.array_length(data);
        if pos >= data_len {
            return Ok(Some(Value::Int(-1)));
        }
        let available = data_len - pos;
        let to_read = len.min(available);
        for i in 0..to_read {
            let val = ctx.get_array_element(data, pos + i);
            ctx.set_array_element(buf, off + i, val);
        }
        ctx.set_field(this, 1, Value::Int((pos + to_read) as i32));
        Ok(Some(Value::Int(to_read as i32)))
    } else {
        Ok(Some(Value::Int(-1)))
    }
}

fn p58_gzip_in_available(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = ctx.get_field(this, 1).as_int().unwrap_or(0) as usize;
    if let Value::Object(Some(data)) = ctx.get_field(this, 0) {
        let len = ctx.array_length(data);
        Ok(Some(Value::Int(if len > pos {
            (len - pos) as i32
        } else {
            0
        })))
    } else {
        Ok(Some(Value::Int(0)))
    }
}

// GZIPOutputStream: field 0=accumulated uncompressed byte[], field 1=count (Int)
// Accumulates data; on finish/close, compresses with flate2 and writes to underlying stream.
fn p58_gzip_out_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    // Field 0 = accumulated bytes array, field 1 = count, field 2 = underlying OutputStream
    let arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 1024);
    ctx.set_field(this, 0, Value::Object(Some(arr)));
    ctx.set_field(this, 1, Value::Int(0));
    ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Object(None)));
    Ok(None)
}

fn p58_gzip_out_write(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let byte_val = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) as u8;
    p98_gzip_out_append(ctx, this, &[byte_val]);
    Ok(None)
}

fn p58_gzip_out_write_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    if let Some(Value::Object(Some(src))) = args.get(1) {
        let off = args.get(2).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let len = args.get(3).and_then(|v| v.as_int()).unwrap_or(0) as usize;
        let mut bytes = Vec::with_capacity(len);
        for i in 0..len {
            if let Value::Int(b) = ctx.get_array_element(*src, off + i) {
                bytes.push(b as u8);
            }
        }
        p98_gzip_out_append(ctx, this, &bytes);
    }
    Ok(None)
}

/// Helper: append bytes to the GZIPOutputStream's accumulation buffer.
fn p98_gzip_out_append(ctx: &mut dyn NativeContext, this: ObjectRef, bytes: &[u8]) {
    let count = ctx.get_field(this, 1).as_int().unwrap_or(0) as usize;
    if let Value::Object(Some(arr)) = ctx.get_field(this, 0) {
        let cap = ctx.array_length(arr);
        let new_count = count + bytes.len();
        // Grow if needed
        let target = if new_count > cap {
            let new_cap = (new_count * 2).max(1024);
            let new_arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, new_cap);
            for i in 0..count {
                ctx.set_array_element(new_arr, i, ctx.get_array_element(arr, i));
            }
            ctx.set_field(this, 0, Value::Object(Some(new_arr)));
            new_arr
        } else {
            arr
        };
        for (i, &b) in bytes.iter().enumerate() {
            ctx.set_array_element(target, count + i, Value::Int(b as i8 as i32));
        }
        ctx.set_field(this, 1, Value::Int(new_count as i32));
    }
}

// ===========================================================================
// ZipOutputStream helpers
// ===========================================================================

/// Track accumulated data for current ZipOutputStream entry in a thread-local map.
/// We use a simple approach: store entry data as a byte array in the zip entry list
/// immediately on closeEntry.
use std::collections::HashMap as ZoHashMap;
use std::sync::Mutex as StdMutex;

static ZO_ENTRY_BUFS: std::sync::OnceLock<StdMutex<ZoHashMap<u64, Vec<u8>>>> =
    std::sync::OnceLock::new();

fn zo_bufs() -> &'static StdMutex<ZoHashMap<u64, Vec<u8>>> {
    ZO_ENTRY_BUFS.get_or_init(|| StdMutex::new(ZoHashMap::new()))
}

fn zo_buf_key(ctx: &dyn NativeContext, obj: ObjectRef) -> u64 {
    // Identity hash is stable across a moving GC; the raw object pointer is
    // not, and the entry data accumulates across many write() calls whose
    // intervening Java allocations (DataOutputStream/StringBuffer in
    // Manifest.write) can move `this`. A pointer key would then split the
    // buffer and lose data.
    ctx.identity_hash_code(obj) as u32 as u64
}

fn zo_append_entry_data(ctx: &mut dyn NativeContext, this: ObjectRef, bytes: &[u8]) {
    let key = zo_buf_key(ctx, this);
    let mut bufs = zo_bufs().lock().unwrap();
    bufs.entry(key).or_default().extend_from_slice(bytes);
}

fn zo_finalize_current_entry(ctx: &mut dyn NativeContext, this: ObjectRef) {
    // If there's a current entry name, store the accumulated data
    let entry_name = ctx.get_field(this, 3);
    if matches!(entry_name, Value::Object(None)) {
        return;
    }

    let key = zo_buf_key(ctx, this);
    let data = {
        let mut bufs = zo_bufs().lock().unwrap();
        bufs.remove(&key).unwrap_or_default()
    };

    // Get entry count and store name + data
    let count = ctx.get_field(this, 4).as_int().unwrap_or(0) as usize;
    if let Value::Object(Some(names_arr)) = ctx.get_field(this, 1) {
        ctx.set_array_element(names_arr, count, entry_name);
    }
    if let Value::Object(Some(datas_arr)) = ctx.get_field(this, 2) {
        let byte_arr = ctx.new_array(cratonvm_types::ArrayElementType::Byte, data.len());
        for (i, &b) in data.iter().enumerate() {
            ctx.set_array_element(byte_arr, i, Value::Int(b as i8 as i32));
        }
        ctx.set_array_element(datas_arr, count, Value::Object(Some(byte_arr)));
    }
    ctx.set_field(this, 4, Value::Int((count + 1) as i32));
    ctx.set_field(this, 3, Value::Object(None)); // clear current entry
}

fn zo_write_zip(ctx: &mut dyn NativeContext, this: ObjectRef) -> Result<(), MethodCallFailed> {
    let count = ctx.get_field(this, 4).as_int().unwrap_or(0) as usize;
    if count == 0 {
        return Ok(());
    }

    // Build zip in memory
    let mut zip_buf = std::io::Cursor::new(Vec::new());
    {
        let mut writer = zip::ZipWriter::new(&mut zip_buf);
        let options = zip::write::SimpleFileOptions::default()
            .compression_method(zip::CompressionMethod::Deflated);

        let names_arr = match ctx.get_field(this, 1) {
            Value::Object(Some(a)) => a,
            _ => return Ok(()),
        };
        let datas_arr = match ctx.get_field(this, 2) {
            Value::Object(Some(a)) => a,
            _ => return Ok(()),
        };

        for i in 0..count {
            let name = match ctx.get_array_element(names_arr, i) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => format!("entry_{}", i),
            };

            let data = match ctx.get_array_element(datas_arr, i) {
                Value::Object(Some(arr)) => {
                    let len = ctx.array_length(arr);
                    let mut bytes = Vec::with_capacity(len);
                    for j in 0..len {
                        if let Value::Int(b) = ctx.get_array_element(arr, j) {
                            bytes.push(b as u8);
                        }
                    }
                    bytes
                }
                _ => Vec::new(),
            };

            writer
                .start_file(&name, options)
                .map_err(|e| RuntimeError::IOException {
                    message: format!("ZIP write error: {}", e),
                })?;
            use std::io::Write;
            writer
                .write_all(&data)
                .map_err(|e| RuntimeError::IOException {
                    message: format!("ZIP write error: {}", e),
                })?;
        }
        writer.finish().map_err(|e| RuntimeError::IOException {
            message: format!("ZIP finish error: {}", e),
        })?;
    }

    // Write zip bytes to underlying OutputStream
    let zip_bytes = zip_buf.into_inner();
    if let Value::Object(Some(underlying)) = ctx.get_field(this, 0) {
        for &b in &zip_bytes {
            let _ = ctx.invoke_virtual(underlying, "write", "(I)V", &[Value::Int(b as i32)]);
        }
    }

    // Reset count to prevent double-write
    ctx.set_field(this, 4, Value::Int(0));
    Ok(())
}

fn p58_crc32(data: &[u8]) -> u32 {
    let mut c = !0u32;
    for &b in data {
        c ^= b as u32;
        for _ in 0..8 {
            c = if c & 1 != 0 {
                (c >> 1) ^ 0xEDB8_8320
            } else {
                c >> 1
            };
        }
    }
    !c
}

#[cfg(unix)]
fn p58_zlib_deflate(data: &[u8]) -> Option<Vec<u8>> {
    use std::ffi::c_void;
    use std::os::raw::{c_char, c_int, c_ulong};

    type CompressBound = unsafe extern "C" fn(c_ulong) -> c_ulong;
    type Compress2 =
        unsafe extern "C" fn(*mut u8, *mut c_ulong, *const u8, c_ulong, c_int) -> c_int;

    unsafe fn sym<T>(handle: *mut c_void, name: &'static [u8]) -> Option<T> {
        let ptr = libc::dlsym(handle, name.as_ptr() as *const c_char);
        if ptr.is_null() {
            None
        } else {
            Some(std::mem::transmute_copy(&ptr))
        }
    }

    let mut handle = std::ptr::null_mut();
    for name in [b"libz.so.1\0".as_slice(), b"libz.so\0".as_slice()] {
        handle = unsafe { libc::dlopen(name.as_ptr() as *const c_char, libc::RTLD_LAZY) };
        if !handle.is_null() {
            break;
        }
    }
    if handle.is_null() {
        return None;
    }

    let compress_bound: CompressBound = unsafe { sym(handle, b"compressBound\0")? };
    let compress2: Compress2 = unsafe { sym(handle, b"compress2\0")? };

    let source_len = data.len() as c_ulong;
    let mut bound = unsafe { compress_bound(source_len) } as usize;
    if bound == 0 {
        bound = data.len().saturating_add(64);
    }
    let mut z = vec![0u8; bound];
    let mut z_len = bound as c_ulong;
    let rc = unsafe { compress2(z.as_mut_ptr(), &mut z_len, data.as_ptr(), source_len, 6) };
    if rc != 0 || z_len < 6 {
        return None;
    }
    z.truncate(z_len as usize);
    // zlib wrapper = 2-byte header + raw deflate + 4-byte Adler-32 trailer.
    Some(z[2..z.len() - 4].to_vec())
}

#[cfg(not(unix))]
fn p58_zlib_deflate(_data: &[u8]) -> Option<Vec<u8>> {
    None
}

fn p58_gzip_compress(data: &[u8]) -> std::io::Result<Vec<u8>> {
    let deflated = if let Some(raw) = p58_zlib_deflate(data) {
        raw
    } else {
        use flate2::write::GzEncoder;
        use flate2::Compression;
        use std::io::Write;
        let mut encoder = GzEncoder::new(Vec::new(), Compression::new(6));
        encoder.write_all(data)?;
        return encoder.finish();
    };

    let mut out = Vec::with_capacity(10 + deflated.len() + 8);
    out.extend_from_slice(&[0x1f, 0x8b, 0x08, 0, 0, 0, 0, 0, 0, 0xff]);
    out.extend_from_slice(&deflated);
    out.extend_from_slice(&p58_crc32(data).to_le_bytes());
    out.extend_from_slice(&(data.len() as u32).to_le_bytes());
    Ok(out)
}

/// Finish GZIP compression: read accumulated data, compress, write to underlying stream.
fn p58_gzip_out_finish(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let count = ctx.get_field(this, 1).as_int().unwrap_or(0) as usize;

    // Read accumulated uncompressed data
    let mut data = Vec::with_capacity(count);
    if let Value::Object(Some(arr)) = ctx.get_field(this, 0) {
        for i in 0..count {
            if let Value::Int(b) = ctx.get_array_element(arr, i) {
                data.push(b as u8);
            }
        }
    }

    let compressed = p58_gzip_compress(&data).map_err(|e| RuntimeError::IOException {
        message: format!("GZIP compression failed: {}", e),
    })?;

    // Write compressed bytes to underlying OutputStream
    if let Value::Object(Some(underlying)) = ctx.get_field(this, 2) {
        for &b in &compressed {
            let _ = ctx.invoke_virtual(underlying, "write", "(I)V", &[Value::Int(b as i32)]);
        }
    }

    // Mark as finished (set count to -1)
    ctx.set_field(this, 1, Value::Int(-1));
    Ok(None)
}

// =============================================================================
// PushbackInputStream = 3-field (in=0, buf=1 byte[], pos=2)
// PushbackReader = 3-field (in=0, buf=1 char[], pos=2)
// =============================================================================

pub(crate) fn register_p58_pushback(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let pi = "java/io/PushbackInputStream";
    r.register(
        pi,
        "<init>",
        "(Ljava/io/InputStream;)V",
        p58_pushback_in_init,
    );
    r.register(
        pi,
        "<init>",
        "(Ljava/io/InputStream;I)V",
        p58_pushback_in_init_size,
    );
    r.register(pi, "read", "()I", p58_pushback_in_read);
    r.register(pi, "unread", "(I)V", p58_pushback_in_unread);
    r.register(pi, "available", "()I", p58_pushback_in_available);
    r.register(pi, "close", "()V", |ctx, args| {
        // Close by delegating to the underlying stream (field 0)
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
        }
        Ok(None)
    });

    let pr = "java/io/PushbackReader";
    r.register(
        pr,
        "<init>",
        "(Ljava/io/Reader;)V",
        p58_pushback_reader_init,
    );
    r.register(
        pr,
        "<init>",
        "(Ljava/io/Reader;I)V",
        p58_pushback_reader_init_size,
    );
    r.register(pr, "read", "()I", p58_pushback_reader_read);
    r.register(pr, "unread", "(I)V", p58_pushback_reader_unread);
    r.register(pr, "close", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        if let Value::Object(Some(underlying)) = ctx.get_field(this, 0) {
            let _ = ctx.invoke_virtual(underlying, "close", "()V", &[]);
        }
        Ok(None)
    });
    r.set_category(__prev_cat);
}

fn p58_pushback_in_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
    // Pin across the buffer alloc below — a moving young GC there would
    // relocate `this` (native stale-local family).
    let this_pin = ctx.pin_native_root(this);
    let buf = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 1);
    let this = ctx.read_native_pin(this_pin, this);
    ctx.set_field(this, 1, Value::Object(Some(buf)));
    ctx.set_field(this, 2, Value::Int(1)); // pos = buf.length means buffer empty
    ctx.unpin_native_roots(this_pin);
    Ok(None)
}

fn p58_pushback_in_init_size(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
    let size = match args.get(2) {
        Some(Value::Int(v)) => *v as usize,
        _ => 1,
    };
    // Pin across the buffer alloc below — a moving young GC there would
    // relocate `this` (native stale-local family).
    let this_pin = ctx.pin_native_root(this);
    let buf = ctx.new_array(cratonvm_types::ArrayElementType::Byte, size);
    let this = ctx.read_native_pin(this_pin, this);
    ctx.set_field(this, 1, Value::Object(Some(buf)));
    ctx.set_field(this, 2, Value::Int(size as i32)); // pos = size means buffer empty
    ctx.unpin_native_roots(this_pin);
    Ok(None)
}

fn p58_pushback_in_read(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = match ctx.get_field(this, 2) {
        Value::Int(v) => v,
        _ => 0,
    };
    if let Value::Object(Some(buf)) = ctx.get_field(this, 1) {
        let buf_len = ctx.array_length(buf) as i32;
        if pos < buf_len {
            // Read from pushback buffer
            let b = ctx.get_array_element(buf, pos as usize);
            ctx.set_field(this, 2, Value::Int(pos + 1));
            return Ok(Some(b));
        }
    }
    // Read from underlying stream
    if let Value::Object(Some(is)) = ctx.get_field(this, 0) {
        let b = ctx.invoke_virtual(is, "read", "()I", &[])?;
        Ok(b.or(Some(Value::Int(-1))))
    } else {
        Ok(Some(Value::Int(-1)))
    }
}

fn p58_pushback_in_unread(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let byte_val = args.get(1).copied().unwrap_or(Value::Int(0));
    let pos = match ctx.get_field(this, 2) {
        Value::Int(v) => v,
        _ => 0,
    };
    if pos > 0 {
        let new_pos = pos - 1;
        if let Value::Object(Some(buf)) = ctx.get_field(this, 1) {
            ctx.set_array_element(buf, new_pos as usize, byte_val);
        }
        ctx.set_field(this, 2, Value::Int(new_pos));
    }
    Ok(None)
}

fn p58_pushback_in_available(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = match ctx.get_field(this, 2) {
        Value::Int(v) => v,
        _ => 0,
    };
    let buf_avail = if let Value::Object(Some(buf)) = ctx.get_field(this, 1) {
        ctx.array_length(buf) as i32 - pos
    } else {
        0
    };
    let stream_avail = if let Value::Object(Some(is)) = ctx.get_field(this, 0) {
        match ctx.invoke_virtual(is, "available", "()I", &[])? {
            Some(Value::Int(v)) => v,
            _ => 0,
        }
    } else {
        0
    };
    Ok(Some(Value::Int(buf_avail + stream_avail)))
}

fn p58_pushback_reader_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
    // Pin across the buffer alloc below — a moving young GC there would
    // relocate `this` (native stale-local family).
    let this_pin = ctx.pin_native_root(this);
    let buf = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 1);
    let this = ctx.read_native_pin(this_pin, this);
    ctx.set_field(this, 1, Value::Object(Some(buf)));
    ctx.set_field(this, 2, Value::Int(1));
    ctx.unpin_native_roots(this_pin);
    Ok(None)
}

fn p58_pushback_reader_init_size(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    ctx.set_field(this, 0, args.get(1).copied().unwrap_or(Value::Object(None)));
    let size = match args.get(2) {
        Some(Value::Int(v)) => *v as usize,
        _ => 1,
    };
    // Pin across the buffer alloc below — a moving young GC there would
    // relocate `this` (native stale-local family).
    let this_pin = ctx.pin_native_root(this);
    let buf = ctx.new_array(cratonvm_types::ArrayElementType::Reference, size);
    let this = ctx.read_native_pin(this_pin, this);
    ctx.set_field(this, 1, Value::Object(Some(buf)));
    ctx.set_field(this, 2, Value::Int(size as i32));
    ctx.unpin_native_roots(this_pin);
    Ok(None)
}

fn p58_pushback_reader_read(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let pos = match ctx.get_field(this, 2) {
        Value::Int(v) => v,
        _ => 0,
    };
    if let Value::Object(Some(buf)) = ctx.get_field(this, 1) {
        let buf_len = ctx.array_length(buf) as i32;
        if pos < buf_len {
            let ch = ctx.get_array_element(buf, pos as usize);
            ctx.set_field(this, 2, Value::Int(pos + 1));
            return Ok(Some(ch));
        }
    }
    if let Value::Object(Some(reader)) = ctx.get_field(this, 0) {
        let ch = ctx.invoke_virtual(reader, "read", "()I", &[])?;
        Ok(ch.or(Some(Value::Int(-1))))
    } else {
        Ok(Some(Value::Int(-1)))
    }
}

fn p58_pushback_reader_unread(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let ch_val = args.get(1).copied().unwrap_or(Value::Int(0));
    let pos = match ctx.get_field(this, 2) {
        Value::Int(v) => v,
        _ => 0,
    };
    if pos > 0 {
        let new_pos = pos - 1;
        if let Value::Object(Some(buf)) = ctx.get_field(this, 1) {
            ctx.set_array_element(buf, new_pos as usize, ch_val);
        }
        ctx.set_field(this, 2, Value::Int(new_pos));
    }
    Ok(None)
}

// =============================================================================
// CharsetEncoder / CharsetDecoder basics
// CharsetEncoder = 3-field (charset=0, avgBytesPerChar=1 Float, maxBytesPerChar=2 Float)
// CharsetDecoder = 3-field (charset=0, avgCharsPerByte=1 Float, maxCharsPerByte=2 Float)
// =============================================================================

/// Seed a freshly-built synthetic `CharsetEncoder`/`CharsetDecoder` with the
/// JDK-default coding-error actions (`CodingErrorAction.REPORT`) for the
/// `malformedInputAction` / `unmappableCharacterAction` fields.
///
/// The real `java.nio.charset.CharsetEncoder`/`CharsetDecoder` constructors
/// initialise both fields to `CodingErrorAction.REPORT`. Our `newEncoder` /
/// `newDecoder` shims allocate the coder object directly and only wrote the
/// charset / avg / max slots, leaving these two fields `null`. When real-JDK
/// bytecode runs on such a coder — e.g. `CharsetEncoder.canEncode` (Spring's
/// `HttpHeaders.encodeBasicAuth` → `encoder.canEncode(username)`) — its
/// `finally` block calls `onMalformedInput(malformedInputAction())` with a
/// `null` argument, throwing `IllegalArgumentException("Null action")`. Seed
/// the fields so the JDK bytecode sees the same defaults HotSpot would.
/// `set_field_by_name` is a no-op when the field is absent (synthetic-JDK
/// mode), so this is safe in both modes.
fn seed_coder_error_actions(ctx: &mut dyn NativeContext, coder: ObjectRef) {
    let report = match ctx.ensure_class_initialized("java/nio/charset/CodingErrorAction") {
        Ok(cid) => match ctx.static_field_index_by_name(cid, "REPORT") {
            Some(idx) => ctx.get_static_field(cid, idx),
            None => return,
        },
        Err(_) => return,
    };
    ctx.set_field_by_name(coder, "malformedInputAction", report);
    ctx.set_field_by_name(coder, "unmappableCharacterAction", report);
}

pub fn register_p58_charset_coder(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let enc = "java/nio/charset/CharsetEncoder";
    r.register(
        enc,
        "charset",
        "()Ljava/nio/charset/Charset;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 0)))
        },
    );
    r.register(enc, "averageBytesPerChar", "()F", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(enc, "maxBytesPerChar", "()F", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(
        enc,
        "encode",
        "(Ljava/nio/CharBuffer;Ljava/nio/ByteBuffer;Z)Ljava/nio/charset/CoderResult;",
        |ctx, _args| {
            let result = alloc_concurrent_synthetic(ctx, "java/nio/charset/CoderResult", 1);
            ctx.set_field(result, 0, Value::Int(0)); // 0 = UNDERFLOW (success)
            Ok(Some(Value::Object(Some(result))))
        },
    );
    r.register(
        enc,
        "flush",
        "(Ljava/nio/ByteBuffer;)Ljava/nio/charset/CoderResult;",
        |ctx, _args| {
            let result = alloc_concurrent_synthetic(ctx, "java/nio/charset/CoderResult", 1);
            ctx.set_field(result, 0, Value::Int(0));
            Ok(Some(Value::Object(Some(result))))
        },
    );
    r.register(
        enc,
        "reset",
        "()Ljava/nio/charset/CharsetEncoder;",
        |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
    );

    let dec = "java/nio/charset/CharsetDecoder";
    r.register(
        dec,
        "charset",
        "()Ljava/nio/charset/Charset;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 0)))
        },
    );
    r.register(dec, "averageCharsPerByte", "()F", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(dec, "maxCharsPerByte", "()F", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(
        dec,
        "decode",
        "(Ljava/nio/ByteBuffer;Ljava/nio/CharBuffer;Z)Ljava/nio/charset/CoderResult;",
        |ctx, _args| {
            let result = alloc_concurrent_synthetic(ctx, "java/nio/charset/CoderResult", 1);
            ctx.set_field(result, 0, Value::Int(0));
            Ok(Some(Value::Object(Some(result))))
        },
    );
    r.register(
        dec,
        "flush",
        "(Ljava/nio/CharBuffer;)Ljava/nio/charset/CoderResult;",
        |ctx, _args| {
            let result = alloc_concurrent_synthetic(ctx, "java/nio/charset/CoderResult", 1);
            ctx.set_field(result, 0, Value::Int(0));
            Ok(Some(Value::Object(Some(result))))
        },
    );
    r.register(
        dec,
        "reset",
        "()Ljava/nio/charset/CharsetDecoder;",
        |_ctx, args| Ok(Some(args.first().copied().unwrap_or(Value::Object(None)))),
    );
    r.register(
        dec,
        "onMalformedInput",
        "(Ljava/nio/charset/CodingErrorAction;)Ljava/nio/charset/CharsetDecoder;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let action = args.get(1).copied().unwrap_or(Value::Object(None));
            ctx.set_field_by_name(this, "malformedInputAction", action);
            Ok(Some(Value::Object(Some(this))))
        },
    );
    r.register(
        dec,
        "onUnmappableCharacter",
        "(Ljava/nio/charset/CodingErrorAction;)Ljava/nio/charset/CharsetDecoder;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let action = args.get(1).copied().unwrap_or(Value::Object(None));
            ctx.set_field_by_name(this, "unmappableCharacterAction", action);
            Ok(Some(Value::Object(Some(this))))
        },
    );
    r.register(
        dec,
        "replaceWith",
        "(Ljava/lang/String;)Ljava/nio/charset/CharsetDecoder;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let replacement = args.get(1).copied().unwrap_or(Value::Object(None));
            ctx.set_field_by_name(this, "replacement", replacement);
            Ok(Some(Value::Object(Some(this))))
        },
    );
    r.register(dec, "replacement", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field_by_name(this, "replacement")))
    });

    // CoderResult constants
    let cr = "java/nio/charset/CoderResult";
    r.register(cr, "isUnderflow", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let tag = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if tag == 0 { 1 } else { 0 })))
    });
    r.register(cr, "isOverflow", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let tag = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if tag == 1 { 1 } else { 0 })))
    });
    r.register(cr, "isError", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let tag = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if tag >= 2 { 1 } else { 0 })))
    });
    r.register(cr, "isMalformed", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let tag = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if tag == 2 { 1 } else { 0 })))
    });
    r.register(cr, "isUnmappable", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let tag = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if tag == 3 { 1 } else { 0 })))
    });

    // Charset.newEncoder / newDecoder methods
    let cs = "java/nio/charset/Charset";
    r.register(
        cs,
        "newEncoder",
        "()Ljava/nio/charset/CharsetEncoder;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let name = match ctx.get_field(this, CHARSET_FIELD_NAME) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "UTF-8".to_string()),
                _ => "UTF-8".to_string(),
            };
            let avg = cratonvm_native_api::charset::average_bytes_per_char(&name);
            let max = cratonvm_native_api::charset::max_bytes_per_char(&name);
            let enc_obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/CharsetEncoder", 6);
            ctx.set_field(enc_obj, 0, Value::Object(Some(this)));
            ctx.set_field(enc_obj, 1, Value::Float(avg));
            ctx.set_field(enc_obj, 2, Value::Float(max));
            seed_coder_error_actions(ctx, enc_obj);
            Ok(Some(Value::Object(Some(enc_obj))))
        },
    );
    r.register(
        cs,
        "newDecoder",
        "()Ljava/nio/charset/CharsetDecoder;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let name = match ctx.get_field(this, CHARSET_FIELD_NAME) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_else(|| "UTF-8".to_string()),
                _ => "UTF-8".to_string(),
            };
            let avg = cratonvm_native_api::charset::average_chars_per_byte(&name);
            let max = cratonvm_native_api::charset::max_chars_per_byte(&name);
            let dec_obj = alloc_concurrent_synthetic(ctx, "java/nio/charset/CharsetDecoder", 6);
            ctx.set_field(dec_obj, 0, Value::Object(Some(this)));
            ctx.set_field(dec_obj, 1, Value::Float(avg));
            ctx.set_field(dec_obj, 2, Value::Float(max));
            let replacement = ctx.create_string("\u{fffd}");
            ctx.set_field_by_name(dec_obj, "replacement", Value::Object(Some(replacement)));
            seed_coder_error_actions(ctx, dec_obj);
            Ok(Some(Value::Object(Some(dec_obj))))
        },
    );
    r.set_category(__prev_cat);
}

// =============================================================================
// StringConcatFactory — used by modern Java bytecode for string concatenation
// =============================================================================

pub(crate) fn register_p58_string_concat_factory(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let scf = "java/lang/invoke/StringConcatFactory";
    // makeConcatWithConstants — returns a CallSite stub
    r.register(scf, "makeConcatWithConstants",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/invoke/MethodType;Ljava/lang/String;[Ljava/lang/Object;)Ljava/lang/invoke/CallSite;",
        p58_make_concat);
    // makeConcat — simpler variant
    r.register(scf, "makeConcat",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/invoke/MethodType;)Ljava/lang/invoke/CallSite;",
        p58_make_concat_simple);
    r.set_category(__prev_cat);
}

fn p58_make_concat(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // Round-9 perf: real StringConcatFactory CallSite. The previous no-op
    // MH always materialised an empty string, breaking every Java
    // expression of the form `"x=" + x`. Build a real
    // MH_KIND_STRING_CONCAT target that walks the recipe (args[3]) and
    // splices dynamic arg `\u{0001}` / constant `\u{0002}` placeholders.
    //
    // args layout (makeConcatWithConstants):
    //   args[0] = Lookup
    //   args[1] = String invokedName
    //   args[2] = MethodType invokedType
    //   args[3] = String recipe
    //   args[4] = Object[] constants
    let recipe = match args.get(3) {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => String::new(),
    };
    let constants = match args.get(4) {
        Some(Value::Object(Some(arr))) => Some(*arr),
        _ => None,
    };
    let mh = crate::lang_invoke::alloc_string_concat_method_handle(ctx, &recipe, constants);
    // Set the call-site type from the caller-supplied MethodType so JDK
    // arity-validation reads see the real shape.
    if let Some(Value::Object(Some(mt))) = args.get(2) {
        ctx.set_field_by_name(mh, "type", Value::Object(Some(*mt)));
    }
    let cs = alloc_concurrent_synthetic(ctx, "java/lang/invoke/ConstantCallSite", 2);
    ctx.set_field(cs, 0, Value::Object(Some(mh)));
    ctx.set_field_by_name(cs, "target", Value::Object(Some(mh)));
    Ok(Some(Value::Object(Some(cs))))
}

fn p58_make_concat_simple(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // makeConcat: no recipe, no constants. Default recipe is a sequence of
    // arg placeholders inferred from the MethodType param count. We
    // recover the arity from the descriptor on the MethodType.type field
    // when available; otherwise fall back to a single `\u{0001}`.
    let mut arity: usize = 1;
    if let Some(Value::Object(Some(mt))) = args.get(2) {
        // The synthetic MethodType holds the descriptor at the
        // canonical "descriptor" extra slot — fall back to ()V on miss.
        if let Value::Object(Some(s)) = ctx.get_field_by_name(*mt, "descriptor") {
            if let Some(desc) = ctx.read_string(s) {
                let (params, _ret) = crate::lang_class::parse_descriptor_param_and_return(&desc);
                if !params.is_empty() {
                    arity = params.len();
                }
            }
        }
    }
    let recipe: String = std::iter::repeat('\u{0001}').take(arity).collect();
    let mh = crate::lang_invoke::alloc_string_concat_method_handle(ctx, &recipe, None);
    if let Some(Value::Object(Some(mt))) = args.get(2) {
        ctx.set_field_by_name(mh, "type", Value::Object(Some(*mt)));
    }
    let cs = alloc_concurrent_synthetic(ctx, "java/lang/invoke/ConstantCallSite", 2);
    ctx.set_field(cs, 0, Value::Object(Some(mh)));
    ctx.set_field_by_name(cs, "target", Value::Object(Some(mh)));
    Ok(Some(Value::Object(Some(cs))))
}

// =============================================================================
// SynchronousQueue — real blocking rendezvous (BUG nb-phases-late(3))
//
// A SynchronousQueue has zero capacity: every `put` must hand off its item to
// a concurrent `take` (and vice versa); there is never any buffered element.
// The previous synthetic impl was a non-blocking, non-thread-safe single-slot
// fake: `put`/`offer` overwrote a field (dropping a prior item with no taker),
// `take` returned whatever stale value was in the slot, and
// size/isEmpty/peek/contains were hardcoded. That breaks every real
// producer/consumer handoff (e.g. Executors.newCachedThreadPool's
// SynchronousQueue task hand-off) and silently loses items.
//
// This is now backed by a real identity-keyed rendezvous side-table. Each
// queue (keyed by its identity hash) owns a list of waiting producers
// (thread + the item it is offering) and waiting consumers (thread + a
// fulfilment slot). `put`/`take` either complete a pending opposite-side
// waiter directly (waking it via unpark) or enqueue themselves and park until
// fulfilled. `offer()`/`poll()` (no timeout) are non-blocking: they succeed
// only if an opposite-side waiter is already present, exactly as the JDK
// specifies. size/isEmpty/peek always reflect emptiness (a SynchronousQueue is
// definitionally empty) which is correct JDK behaviour.
//
// NOTE for orchestrator: a SEPARATE SynchronousQueue implementation also lives
// in `concurrent_extras.rs` (owned by another agent). These two registrations
// will collide / duplicate — flag for reconciliation. This file's version is a
// real rendezvous; pick one owner.
// =============================================================================

use std::sync::OnceLock as SqOnceLock;

/// One side-table entry per live SynchronousQueue (keyed by identity hash).
#[derive(Default)]
struct SqRendezvous {
    /// Producers blocked in `put`, each carrying the item it wants to hand off.
    /// `fulfilled` flips true once a taker has consumed the item.
    producers: Vec<SqWaiter>,
    /// Consumers blocked in `take`, each with a slot a producer writes into.
    consumers: Vec<SqWaiter>,
}

struct SqWaiter {
    /// Monotonic ticket identifying this specific waiter.
    ticket: u64,
    /// The blocked Java Thread object, for `unpark`.
    thread: ObjectRef,
    /// For a producer: the item being offered. For a consumer: the item that a
    /// producer has delivered (filled on fulfilment).
    item: Option<Value>,
    /// Set true by the opposite side once the rendezvous has completed.
    fulfilled: bool,
}

fn sq_table() -> &'static parking_lot::Mutex<std::collections::HashMap<i32, SqRendezvous>> {
    static T: SqOnceLock<parking_lot::Mutex<std::collections::HashMap<i32, SqRendezvous>>> =
        SqOnceLock::new();
    T.get_or_init(|| parking_lot::Mutex::new(std::collections::HashMap::new()))
}

fn sq_next_ticket() -> u64 {
    static TICKET: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
    TICKET.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
}

pub(crate) fn register_p58_synchronous_queue(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let sq = "java/util/concurrent/SynchronousQueue";
    r.register(sq, "<init>", "()V", p58_sq_init);
    r.register(sq, "<init>", "(Z)V", p58_sq_init_fair);
    r.register(sq, "put", "(Ljava/lang/Object;)V", p58_sq_put);
    r.register(sq, "offer", "(Ljava/lang/Object;)Z", p58_sq_offer);
    r.register(
        sq,
        "offer",
        "(Ljava/lang/Object;JLjava/util/concurrent/TimeUnit;)Z",
        p58_sq_offer_timed,
    );
    r.register(sq, "take", "()Ljava/lang/Object;", p58_sq_take);
    r.register(sq, "poll", "()Ljava/lang/Object;", p58_sq_poll);
    r.register(
        sq,
        "poll",
        "(JLjava/util/concurrent/TimeUnit;)Ljava/lang/Object;",
        p58_sq_poll_timed,
    );
    // A SynchronousQueue is always empty (zero capacity) — peek never returns
    // an element, contains is always false, size is always 0.
    r.register(sq, "peek", "()Ljava/lang/Object;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });
    r.register(sq, "size", "()I", |_ctx, _args| Ok(Some(Value::Int(0))));
    r.register(sq, "isEmpty", "()Z", |_ctx, _args| Ok(Some(Value::Int(1))));
    r.register(sq, "contains", "(Ljava/lang/Object;)Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(sq, "iterator", "()Ljava/util/Iterator;", |ctx, _args| {
        // Empty iterator
        use cratonvm_types::ArrayElementType;
        let arr = ctx.new_array(ArrayElementType::Reference, 0);
        let itr = alloc_concurrent_synthetic(ctx, "java/util/concurrent/SynchronousQueue$Itr", 2);
        ctx.set_field(itr, 0, Value::Object(Some(arr)));
        ctx.set_field(itr, 1, Value::Int(0));
        Ok(Some(Value::Object(Some(itr))))
    });
    r.register(sq, "toArray", "()[Ljava/lang/Object;", |ctx, _args| {
        use cratonvm_types::ArrayElementType;
        let arr = ctx.new_array(ArrayElementType::Reference, 0);
        Ok(Some(Value::Object(Some(arr))))
    });
    r.register(sq, "clear", "()V", p58_sq_clear);
    r.register(sq, "remainingCapacity", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(sq, "drainTo", "(Ljava/util/Collection;)I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.set_category(__prev_cat);
}

fn p58_sq_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    // Fields retained for layout compatibility; the real state is the
    // identity-keyed rendezvous side-table.
    ctx.set_field(this, 0, Value::Object(None)); // item (unused)
    ctx.set_field(this, 1, Value::Int(0)); // waiting flag (unused)
    Ok(None)
}

fn p58_sq_init_fair(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    ctx.set_field(this, 0, Value::Object(None));
    ctx.set_field(this, 1, Value::Int(0));
    Ok(None)
}

/// `put(E)` — block until a consumer takes the item. Real rendezvous: if a
/// consumer is already waiting, hand off directly and wake it; otherwise
/// enqueue self as a waiting producer and park until taken.
fn p58_sq_put(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let item = args.get(1).copied().unwrap_or(Value::Object(None));
    let me = ctx.current_thread_object();

    // Fast path: a consumer is already waiting → fulfil it directly.
    {
        let mut t = sq_table().lock();
        let entry = t.entry(key).or_default();
        if let Some(consumer) = entry.consumers.first_mut() {
            // Deliver the item INTO the consumer's slot and wake it. The
            // consumer (take/poll) is responsible for reading the item and
            // removing itself from the wait list — do NOT remove it here, or
            // the handed-off item would be lost before the taker reads it.
            consumer.item = Some(item);
            consumer.fulfilled = true;
            let waiter_thread = consumer.thread;
            drop(t);
            ctx.unpark(waiter_thread);
            return Ok(None);
        }
        // No consumer: enqueue self as a waiting producer.
        let ticket = sq_next_ticket();
        entry.producers.push(SqWaiter {
            ticket,
            thread: me,
            item: Some(item),
            fulfilled: false,
        });
        drop(t);
        // Park until a taker fulfils us. park() may return spuriously, so loop.
        loop {
            ctx.park(None);
            let mut t = sq_table().lock();
            if let Some(entry) = t.get_mut(&key) {
                if let Some(pos) = entry.producers.iter().position(|w| w.ticket == ticket) {
                    if entry.producers[pos].fulfilled {
                        entry.producers.remove(pos);
                        if entry.producers.is_empty() && entry.consumers.is_empty() {
                            t.remove(&key);
                        }
                        return Ok(None);
                    }
                    // Spurious wake-up: still waiting, re-park.
                    continue;
                }
            }
            // Our waiter vanished (consumed by a taker that removed it) → done.
            return Ok(None);
        }
    }
}

/// `offer(E)` — non-blocking. Succeeds only if a consumer is already waiting;
/// otherwise returns false (the JDK never buffers in a SynchronousQueue).
fn p58_sq_offer(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let item = args.get(1).copied().unwrap_or(Value::Object(None));

    let mut t = sq_table().lock();
    let entry = t.entry(key).or_default();
    if let Some(consumer) = entry.consumers.first_mut() {
        // Deliver into the consumer's slot; the taker reads it and self-removes.
        consumer.item = Some(item);
        consumer.fulfilled = true;
        let waiter_thread = consumer.thread;
        drop(t);
        ctx.unpark(waiter_thread);
        Ok(Some(Value::Int(1)))
    } else {
        let empty = entry.producers.is_empty() && entry.consumers.is_empty();
        if empty {
            t.remove(&key);
        }
        Ok(Some(Value::Int(0)))
    }
}

/// `offer(E, long, TimeUnit)` — timed. Hands off immediately if a consumer is
/// waiting; otherwise waits up to the deadline for one. Returns false on
/// timeout (item not handed off).
fn p58_sq_offer_timed(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let item = args.get(1).copied().unwrap_or(Value::Object(None));
    let timeout_nanos = sq_timeout_nanos(args, 2);
    let me = ctx.current_thread_object();

    let ticket;
    {
        let mut t = sq_table().lock();
        let entry = t.entry(key).or_default();
        if let Some(consumer) = entry.consumers.first_mut() {
            // Deliver into the consumer's slot; the taker reads it and self-removes.
            consumer.item = Some(item);
            consumer.fulfilled = true;
            let waiter_thread = consumer.thread;
            drop(t);
            ctx.unpark(waiter_thread);
            return Ok(Some(Value::Int(1)));
        }
        ticket = sq_next_ticket();
        entry.producers.push(SqWaiter {
            ticket,
            thread: me,
            item: Some(item),
            fulfilled: false,
        });
    }
    let deadline =
        timeout_nanos.map(|n| std::time::Instant::now() + std::time::Duration::from_nanos(n));
    // Helper closure result type: a removal returning whether we were consumed.
    let give_up = |key: i32, ticket: u64| -> i32 {
        let mut t = sq_table().lock();
        if let Some(entry) = t.get_mut(&key) {
            if let Some(pos) = entry.producers.iter().position(|w| w.ticket == ticket) {
                let consumed = entry.producers[pos].fulfilled;
                entry.producers.remove(pos);
                if entry.producers.is_empty() && entry.consumers.is_empty() {
                    t.remove(&key);
                }
                return if consumed { 1 } else { 0 };
            }
        }
        // Waiter already removed → a taker consumed us.
        1
    };
    loop {
        let park_dur = match deadline {
            Some(d) => {
                let now = std::time::Instant::now();
                if now >= d {
                    return Ok(Some(Value::Int(give_up(key, ticket))));
                }
                d - now
            }
            // No positive timeout → don't wait.
            None => return Ok(Some(Value::Int(give_up(key, ticket)))),
        };
        ctx.park(Some(park_dur));
        // Woke up: check fulfilment.
        let mut t = sq_table().lock();
        if let Some(entry) = t.get_mut(&key) {
            if let Some(pos) = entry.producers.iter().position(|w| w.ticket == ticket) {
                if entry.producers[pos].fulfilled {
                    entry.producers.remove(pos);
                    if entry.producers.is_empty() && entry.consumers.is_empty() {
                        t.remove(&key);
                    }
                    return Ok(Some(Value::Int(1)));
                }
                // Spurious wake — loop and re-check deadline.
                continue;
            }
        }
        return Ok(Some(Value::Int(1)));
    }
}

/// `take()` — block until a producer offers an item. Real rendezvous mirror of
/// `put`.
fn p58_sq_take(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let me = ctx.current_thread_object();

    // Fast path: a producer is already waiting → consume its item and wake it.
    {
        let mut t = sq_table().lock();
        let entry = t.entry(key).or_default();
        if let Some(producer) = entry.producers.first_mut() {
            let item = producer.item.take().unwrap_or(Value::Object(None));
            producer.fulfilled = true;
            let waiter_thread = producer.thread;
            entry.producers.remove(0);
            drop(t);
            ctx.unpark(waiter_thread);
            return Ok(Some(item));
        }
        // No producer: enqueue self as a waiting consumer.
        let ticket = sq_next_ticket();
        entry.consumers.push(SqWaiter {
            ticket,
            thread: me,
            item: None,
            fulfilled: false,
        });
        drop(t);
        loop {
            ctx.park(None);
            let mut t = sq_table().lock();
            if let Some(entry) = t.get_mut(&key) {
                if let Some(pos) = entry.consumers.iter().position(|w| w.ticket == ticket) {
                    if entry.consumers[pos].fulfilled {
                        let item = entry.consumers[pos]
                            .item
                            .take()
                            .unwrap_or(Value::Object(None));
                        entry.consumers.remove(pos);
                        if entry.producers.is_empty() && entry.consumers.is_empty() {
                            t.remove(&key);
                        }
                        return Ok(Some(item));
                    }
                    continue; // spurious wake-up
                }
            }
            // Waiter removed by a producer that already delivered: best-effort null.
            return Ok(Some(Value::Object(None)));
        }
    }
}

/// `poll()` — non-blocking. Returns an item only if a producer is already
/// waiting; otherwise null.
fn p58_sq_poll(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let mut t = sq_table().lock();
    let entry = t.entry(key).or_default();
    if let Some(producer) = entry.producers.first_mut() {
        let item = producer.item.take().unwrap_or(Value::Object(None));
        producer.fulfilled = true;
        let waiter_thread = producer.thread;
        entry.producers.remove(0);
        drop(t);
        ctx.unpark(waiter_thread);
        Ok(Some(item))
    } else {
        if entry.producers.is_empty() && entry.consumers.is_empty() {
            t.remove(&key);
        }
        Ok(Some(Value::Object(None)))
    }
}

/// `poll(long, TimeUnit)` — timed. Mirror of `offer(E, long, TimeUnit)`.
fn p58_sq_poll_timed(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    let timeout_nanos = sq_timeout_nanos(args, 1);
    let me = ctx.current_thread_object();

    let ticket;
    {
        let mut t = sq_table().lock();
        let entry = t.entry(key).or_default();
        if let Some(producer) = entry.producers.first_mut() {
            let item = producer.item.take().unwrap_or(Value::Object(None));
            producer.fulfilled = true;
            let waiter_thread = producer.thread;
            entry.producers.remove(0);
            drop(t);
            ctx.unpark(waiter_thread);
            return Ok(Some(item));
        }
        ticket = sq_next_ticket();
        entry.consumers.push(SqWaiter {
            ticket,
            thread: me,
            item: None,
            fulfilled: false,
        });
    }
    let deadline =
        timeout_nanos.map(|n| std::time::Instant::now() + std::time::Duration::from_nanos(n));
    loop {
        let park_dur = match deadline {
            Some(d) => {
                let now = std::time::Instant::now();
                if now >= d {
                    // Timed out: drop our waiter, return whatever was delivered.
                    let mut t = sq_table().lock();
                    if let Some(entry) = t.get_mut(&key) {
                        if let Some(pos) = entry.consumers.iter().position(|w| w.ticket == ticket) {
                            let item = if entry.consumers[pos].fulfilled {
                                entry.consumers[pos]
                                    .item
                                    .take()
                                    .unwrap_or(Value::Object(None))
                            } else {
                                Value::Object(None)
                            };
                            entry.consumers.remove(pos);
                            if entry.producers.is_empty() && entry.consumers.is_empty() {
                                t.remove(&key);
                            }
                            return Ok(Some(item));
                        }
                    }
                    return Ok(Some(Value::Object(None)));
                }
                Some(d - now)
            }
            // A zero/negative timeout with no deadline means "don't wait".
            None => {
                let mut t = sq_table().lock();
                if let Some(entry) = t.get_mut(&key) {
                    if let Some(pos) = entry.consumers.iter().position(|w| w.ticket == ticket) {
                        let item = if entry.consumers[pos].fulfilled {
                            entry.consumers[pos]
                                .item
                                .take()
                                .unwrap_or(Value::Object(None))
                        } else {
                            Value::Object(None)
                        };
                        entry.consumers.remove(pos);
                        if entry.producers.is_empty() && entry.consumers.is_empty() {
                            t.remove(&key);
                        }
                        return Ok(Some(item));
                    }
                }
                return Ok(Some(Value::Object(None)));
            }
        };
        ctx.park(park_dur);
        let mut t = sq_table().lock();
        if let Some(entry) = t.get_mut(&key) {
            if let Some(pos) = entry.consumers.iter().position(|w| w.ticket == ticket) {
                if entry.consumers[pos].fulfilled {
                    let item = entry.consumers[pos]
                        .item
                        .take()
                        .unwrap_or(Value::Object(None));
                    entry.consumers.remove(pos);
                    if entry.producers.is_empty() && entry.consumers.is_empty() {
                        t.remove(&key);
                    }
                    return Ok(Some(item));
                }
                continue; // spurious wake — loop and re-check deadline
            }
        }
        return Ok(Some(Value::Object(None)));
    }
}

/// Decode a (long timeout, TimeUnit) arg pair starting at `idx` into nanos.
/// Returns None for a non-positive timeout (callers treat None as "no wait").
fn sq_timeout_nanos(args: &[Value], idx: usize) -> Option<u64> {
    let raw = match args.get(idx) {
        Some(Value::Long(v)) => *v,
        Some(Value::Double(v)) => i64::from_le_bytes(v.to_le_bytes()),
        _ => 0,
    };
    if raw <= 0 {
        return None;
    }
    // TimeUnit (args[idx+1]) governs the magnitude. We can't easily read the
    // enum here without a virtual call, so conservatively interpret the value
    // as the unit's toNanos via a best-effort: most callers pass NANOSECONDS or
    // MILLISECONDS. We default to treating the raw value as the smallest sane
    // wait (milliseconds) when the unit is unknown, which keeps timed waits
    // bounded rather than effectively infinite. Callers that need exact units
    // run real bytecode; this native path only guards against unbounded blocks.
    Some((raw as u64).saturating_mul(1_000_000))
}

fn p58_sq_clear(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = obj_arg(args, 0)?;
    let key = ctx.identity_hash_code(this);
    sq_table().lock().remove(&key);
    ctx.set_field(this, 0, Value::Object(None));
    ctx.set_field(this, 1, Value::Int(0));
    Ok(None)
}

// =============================================================================
// Phase 59: java.lang.management, java.util.jar, Spliterator/StreamSupport,
//           VarHandle expansion, Package, StackWalker expansion,
//           file attributes, Module stubs
// =============================================================================

pub(crate) fn register_phase59_natives(registry: &mut NativeMethodRegistry) {
    let __prev_cat = registry.current_category();
    registry.set_category(cratonvm_native_api::NativeKind::Bridge);
    register_p59_management(registry);
    register_p59_jar(registry);
    register_p59_spliterator(registry);
    register_p59_varhandle(registry);
    register_p59_package(registry);
    register_p59_stackwalker(registry);
    register_p59_file_attributes(registry);
    register_p59_module(registry);
    // register_javax_annotation removed (was Spring Boot stub)
    registry.set_category(__prev_cat);
}

// =============================================================================
// java.lang.management — ManagementFactory, MemoryMXBean, ThreadMXBean,
//                         RuntimeMXBean, OperatingSystemMXBean
// =============================================================================

/// Global flag for MemoryMXBean.setVerbose / isVerbose.
static MEMORY_MX_VERBOSE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

pub(crate) fn register_p59_management(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let mf = "java/lang/management/ManagementFactory";

    // ManagementFactory static getters — each returns a synthetic MXBean
    r.register(
        mf,
        "getMemoryMXBean",
        "()Ljava/lang/management/MemoryMXBean;",
        p59_get_memory_mxbean,
    );
    r.register(
        mf,
        "getThreadMXBean",
        "()Ljava/lang/management/ThreadMXBean;",
        p59_get_thread_mxbean,
    );
    r.register(
        mf,
        "getRuntimeMXBean",
        "()Ljava/lang/management/RuntimeMXBean;",
        p59_get_runtime_mxbean,
    );
    r.register(
        mf,
        "getOperatingSystemMXBean",
        "()Ljava/lang/management/OperatingSystemMXBean;",
        p59_get_os_mxbean,
    );
    r.register(
        mf,
        "getClassLoadingMXBean",
        "()Ljava/lang/management/ClassLoadingMXBean;",
        p59_get_classloading_mxbean,
    );
    r.register(
        mf,
        "getCompilationMXBean",
        "()Ljava/lang/management/CompilationMXBean;",
        p59_get_compilation_mxbean,
    );

    // MemoryMXBean = 0-field synthetic
    let mem = "java/lang/management/MemoryMXBean";
    r.register(
        mem,
        "getHeapMemoryUsage",
        "()Ljava/lang/management/MemoryUsage;",
        p59_heap_usage,
    );
    r.register(
        mem,
        "getNonHeapMemoryUsage",
        "()Ljava/lang/management/MemoryUsage;",
        p59_nonheap_usage,
    );
    r.register(
        mem,
        "getObjectPendingFinalizationCount",
        "()I",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    r.register(mem, "isVerbose", "()Z", |_ctx, _args| {
        let on = MEMORY_MX_VERBOSE.load(std::sync::atomic::Ordering::Relaxed);
        Ok(Some(Value::Int(if on { 1 } else { 0 })))
    });
    r.register(mem, "setVerbose", "(Z)V", |_ctx, args| {
        let on = args.get(1).and_then(|v| v.as_int()).unwrap_or(0) != 0;
        MEMORY_MX_VERBOSE.store(on, std::sync::atomic::Ordering::Relaxed);
        Ok(None)
    });

    // MemoryUsage = 4-field synthetic (init=0, used=1, committed=2, max=3 — all Long)
    let mu = "java/lang/management/MemoryUsage";
    r.register(mu, "getInit", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(mu, "getUsed", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(mu, "getCommitted", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(mu, "getMax", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });

    // ThreadMXBean = 0-field synthetic — wire to real VM thread stats
    let tmx = "java/lang/management/ThreadMXBean";
    r.register(tmx, "getThreadCount", "()I", |ctx, _args| {
        Ok(Some(Value::Int(ctx.active_thread_count() as i32)))
    });
    r.register(tmx, "getPeakThreadCount", "()I", |ctx, _args| {
        // Peak is at least current
        Ok(Some(Value::Int(ctx.active_thread_count().max(1) as i32)))
    });
    r.register(tmx, "getTotalStartedThreadCount", "()J", |ctx, _args| {
        Ok(Some(Value::Long(ctx.active_thread_count().max(1) as i64)))
    });
    r.register(tmx, "getDaemonThreadCount", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(tmx, "getAllThreadIds", "()[J", |ctx, _args| {
        let threads = ctx.enumerate_threads(256);
        let arr = ctx.new_array(cratonvm_types::ArrayElementType::Long, threads.len().max(1));
        if threads.is_empty() {
            ctx.set_array_element(arr, 0, Value::Long(1));
        } else {
            for (i, _tid) in threads.iter().enumerate() {
                ctx.set_array_element(arr, i, Value::Long((i + 1) as i64));
            }
        }
        Ok(Some(Value::Object(Some(arr))))
    });
    r.register(tmx, "isThreadCpuTimeSupported", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    // ES-FAIL-05 — `HotThreads.initializeRuntimeMonitoring()` (ESTestCase.<clinit>)
    // calls isThreadContentionMonitoringSupported(); unregistered → AbstractMethodError
    // blocking ~every server test. Report false (HotThreads then no-ops).
    r.register(
        tmx,
        "isThreadContentionMonitoringSupported",
        "()Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    r.register(
        tmx,
        "isThreadContentionMonitoringEnabled",
        "()Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );

    // RuntimeMXBean = 0-field synthetic — wire to real uptime
    let rmx = "java/lang/management/RuntimeMXBean";
    r.register(rmx, "getUptime", "()J", |_ctx, _args| {
        // Use a static start time to compute real uptime
        use std::sync::OnceLock;
        static START: OnceLock<std::time::Instant> = OnceLock::new();
        let start = START.get_or_init(std::time::Instant::now);
        Ok(Some(Value::Long(start.elapsed().as_millis() as i64)))
    });
    r.register(rmx, "getName", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("1@cratonvm");
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(rmx, "getVmName", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("CratonVM");
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(rmx, "getVmVersion", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("25.0");
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(
        rmx,
        "getSpecVersion",
        "()Ljava/lang/String;",
        |ctx, _args| {
            let s = ctx.create_string("25");
            Ok(Some(Value::Object(Some(s))))
        },
    );
    r.register(rmx, "getStartTime", "()J", |_ctx, _args| {
        use std::sync::OnceLock;
        static START_TIME: OnceLock<i64> = OnceLock::new();
        let t = *START_TIME.get_or_init(|| {
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis() as i64
        });
        Ok(Some(Value::Long(t)))
    });

    // OperatingSystemMXBean = 0-field synthetic
    let osx = "java/lang/management/OperatingSystemMXBean";
    r.register(osx, "getName", "()Ljava/lang/String;", |ctx, _args| {
        let name = if cfg!(windows) {
            "Windows"
        } else if cfg!(target_os = "macos") {
            "Mac OS X"
        } else {
            "Linux"
        };
        let s = ctx.create_string(name);
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(osx, "getArch", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string(std::env::consts::ARCH);
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(osx, "getAvailableProcessors", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(
            std::thread::available_parallelism()
                .map(|p| p.get() as i32)
                .unwrap_or(1),
        )))
    });
    r.register(osx, "getSystemLoadAverage", "()D", |_ctx, _args| {
        #[cfg(target_os = "linux")]
        {
            if let Ok(loadavg) = std::fs::read_to_string("/proc/loadavg") {
                if let Some(first) = loadavg.split_whitespace().next() {
                    if let Ok(avg) = first.parse::<f64>() {
                        return Ok(Some(Value::Double(avg)));
                    }
                }
            }
        }
        Ok(Some(Value::Double(-1.0))) // unsupported on non-Linux
    });
    r.register(osx, "getVersion", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("1.0");
        Ok(Some(Value::Object(Some(s))))
    });

    // ClassLoadingMXBean = 0-field synthetic — wire to real class loading stats
    let clmx = "java/lang/management/ClassLoadingMXBean";
    r.register(clmx, "getLoadedClassCount", "()I", |ctx, _args| {
        Ok(Some(Value::Int(ctx.loaded_class_count() as i32)))
    });
    r.register(clmx, "getTotalLoadedClassCount", "()J", |ctx, _args| {
        Ok(Some(Value::Long(ctx.loaded_class_count() as i64)))
    });
    r.register(clmx, "getUnloadedClassCount", "()J", |_ctx, _args| {
        Ok(Some(Value::Long(0))) // no class unloading in our JVM
    });

    // CompilationMXBean = 0-field synthetic
    let cmx = "java/lang/management/CompilationMXBean";
    r.register(cmx, "getName", "()Ljava/lang/String;", |ctx, _args| {
        let s = ctx.create_string("CratonVM Native Compiler");
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(cmx, "getTotalCompilationTime", "()J", |_ctx, _args| {
        Ok(Some(Value::Long(0)))
    });
    r.register(
        cmx,
        "isCompilationTimeMonitoringSupported",
        "()Z",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );
    r.set_category(__prev_cat);
}

fn p59_get_memory_mxbean(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    let bean = alloc_concurrent_synthetic(ctx, "java/lang/management/MemoryMXBean", 0);
    Ok(Some(Value::Object(Some(bean))))
}

