pub(crate) fn register_p61_reflect(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // --- Parameter = 3-field (name=0, modifiers=1, declaringExecutable=2) ---
    let param = "java/lang/reflect/Parameter";
    r.register(param, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(param, "getModifiers", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(param, "getType", "()Ljava/lang/Class;", |_ctx, _args| {
        Ok(Some(Value::Object(None)))
    });
    r.register(
        param,
        "getDeclaringExecutable",
        "()Ljava/lang/reflect/Executable;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            Ok(Some(ctx.get_field(this, 2)))
        },
    );
    r.register(param, "isVarArgs", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(param, "isNamePresent", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(1)))
    });
    r.register(
        param,
        "getAnnotations",
        "()[Ljava/lang/annotation/Annotation;",
        |ctx, _args| {
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(param, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => "arg".to_string(),
        };
        let s = ctx.create_string(&name);
        Ok(Some(Value::Object(Some(s))))
    });

    // --- Executable base methods ---
    let exec = "java/lang/reflect/Executable";
    r.register(
        exec,
        "getParameters",
        "()[Ljava/lang/reflect/Parameter;",
        |ctx, _args| {
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(exec, "getParameterCount", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(
        exec,
        "getTypeParameters",
        "()[Ljava/lang/reflect/TypeVariable;",
        |ctx, _args| {
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(
        exec,
        "getAnnotations",
        "()[Ljava/lang/annotation/Annotation;",
        |ctx, _args| {
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );

    // --- Field annotation methods (real implementations in lib.rs) ---
    let field = "java/lang/reflect/Field";
    r.register(
        field,
        "getAnnotations",
        "()[Ljava/lang/annotation/Annotation;",
        crate::lang_class::native_field_get_annotations,
    );
    r.register(
        field,
        "getAnnotation",
        "(Ljava/lang/Class;)Ljava/lang/annotation/Annotation;",
        crate::lang_class::native_field_get_annotation,
    );
    r.register(
        field,
        "isAnnotationPresent",
        "(Ljava/lang/Class;)Z",
        crate::lang_class::native_field_is_annotation_present,
    );

    // --- Method annotation methods (real implementations in lib.rs) ---
    fn java_utf16_hash(s: &str) -> i32 {
        let mut h = 0i32;
        for ch in s.encode_utf16() {
            h = h.wrapping_mul(31).wrapping_add(ch as i32);
        }
        h
    }

    let method = "java/lang/reflect/Method";
    r.register(
        method,
        "getAnnotations",
        "()[Ljava/lang/annotation/Annotation;",
        crate::lang_class::native_method_get_annotations,
    );
    r.register(
        method,
        "getAnnotation",
        "(Ljava/lang/Class;)Ljava/lang/annotation/Annotation;",
        crate::lang_class::native_method_get_annotation,
    );
    r.register(
        method,
        "isAnnotationPresent",
        "(Ljava/lang/Class;)Z",
        crate::lang_class::native_method_is_annotation_present,
    );
    r.register(method, "hashCode", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let Some((class_id, method_name, _method_desc)) =
            crate::lang_class::method_class_name_desc(ctx, this)
        else {
            return Ok(Some(Value::Int(0)));
        };
        let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();
        Ok(Some(Value::Int(
            java_utf16_hash(&class_name.replace('/', ".")) ^ java_utf16_hash(&method_name),
        )))
    });
    r.register(method, "equals", "(Ljava/lang/Object;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let other = match args.get(1) {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        if this == other {
            return Ok(Some(Value::Int(1)));
        }
        if ctx
            .class_name_of_id(ctx.class_id_of_object(other))
            .as_deref()
            != Some("java/lang/reflect/Method")
        {
            return Ok(Some(Value::Int(0)));
        }
        let left = crate::lang_class::method_class_name_desc(ctx, this);
        let right = crate::lang_class::method_class_name_desc(ctx, other);
        Ok(Some(Value::Int(if left.is_some() && left == right {
            1
        } else {
            0
        })))
    });
    r.register(
        method,
        "getParameterAnnotations",
        "()[[Ljava/lang/annotation/Annotation;",
        crate::lang_class::native_method_get_parameter_annotations,
    );

    // --- Constructor annotation methods ---
    let ctor = "java/lang/reflect/Constructor";
    r.register(
        ctor,
        "getAnnotations",
        "()[Ljava/lang/annotation/Annotation;",
        |ctx, _args| {
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            Ok(Some(Value::Object(Some(arr))))
        },
    );
    r.register(
        ctor,
        "getAnnotation",
        "(Ljava/lang/Class;)Ljava/lang/annotation/Annotation;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.set_category(__prev_cat);
}

// =============================================================================
// java.nio.file — Files.exists/isDirectory, Path expansion
// =============================================================================

pub(crate) fn register_p61_files_path(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let files = "java/nio/file/Files";
    r.register(
        files,
        "exists",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let exists = match vfs_classify(&path_str) {
                    Some(kind) => !matches!(kind, JarFsKind::Absent),
                    None => std::path::Path::new(&path_str).exists(),
                };
                Ok(Some(Value::Int(if exists { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "notExists",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(1))),
                };
                let exists = match vfs_classify(&path_str) {
                    Some(kind) => !matches!(kind, JarFsKind::Absent),
                    None => std::path::Path::new(&path_str).exists(),
                };
                Ok(Some(Value::Int(if !exists { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(1)))
            }
        },
    );
    r.register(
        files,
        "isDirectory",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let is_dir = match vfs_classify(&path_str) {
                    Some(kind) => matches!(kind, JarFsKind::Dir),
                    None => std::path::Path::new(&path_str).is_dir(),
                };
                Ok(Some(Value::Int(if is_dir { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "isRegularFile",
        "(Ljava/nio/file/Path;[Ljava/nio/file/LinkOption;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let is_file = match vfs_classify(&path_str) {
                    Some(kind) => matches!(kind, JarFsKind::File),
                    None => std::path::Path::new(&path_str).is_file(),
                };
                Ok(Some(Value::Int(if is_file { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(files, "size", "(Ljava/nio/file/Path;)J", p59_files_size);
    r.register(
        files,
        "isReadable",
        "(Ljava/nio/file/Path;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let readable = match vfs_classify(&path_str) {
                    Some(kind) => !matches!(kind, JarFsKind::Absent),
                    None => std::path::Path::new(&path_str).exists(),
                };
                Ok(Some(Value::Int(if readable { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
    r.register(
        files,
        "isWritable",
        "(Ljava/nio/file/Path;)Z",
        |ctx, args| {
            if let Some(Value::Object(Some(path_ref))) = args.first() {
                let path_str = match ctx.get_field(*path_ref, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => return Ok(Some(Value::Int(0))),
                };
                let writable = std::fs::metadata(&path_str)
                    .map(|m| !m.permissions().readonly())
                    .unwrap_or(false);
                Ok(Some(Value::Int(if writable { 1 } else { 0 })))
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );

    // --- Path expansion ---
    let path = "java/nio/file/Path";
    r.register(
        path,
        "getFileName",
        "()Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let path_str = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(None))),
            };
            // jar-FS aware: operate on the in-jar entry portion.
            let entry = jarfs_decode(&path_str)
                .map(|(_, e)| e)
                .unwrap_or_else(|| path_str.clone());
            let fname = std::path::Path::new(&entry)
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("");
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 2);
            let s = ctx.create_string(fname);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    // keycloak-15: route through the shared `p57_parent_of` (jar-FS aware +
    // Windows last-separator split that keeps `.`/`..`) instead of Rust's
    // `Path::parent()`, which normalizes a trailing `.` and over-trims. This is
    // the last-registered (winning) `getParent`; keep it identical to the
    // earlier registration so behaviour does not depend on phase order.
    r.register(path, "getParent", "()Ljava/nio/file/Path;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let p = p57_read_path(ctx, this);
        let parent = p57_parent_of(&p);
        if parent.is_empty() {
            Ok(Some(Value::Object(None)))
        } else {
            let result = p57_alloc_path(ctx, &parent);
            Ok(Some(Value::Object(Some(result))))
        }
    });
    r.register(
        path,
        "toAbsolutePath",
        "()Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let path_str = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(Some(this)))),
            };
            // jar-FS paths are already absolute within the mounted filesystem.
            let abs = if jarfs_decode(&path_str).is_some() {
                path_str
            } else {
                p57_absolute_path_string(&path_str)
            };
            let p = p57_alloc_path(ctx, &abs);
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(
        path,
        "resolve",
        "(Ljava/lang/String;)Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let base = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let other = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let resolved = if jarfs_decode(&base).is_some() {
                p57_resolve_paths(&base, &other)
            } else {
                std::path::Path::new(&base)
                    .join(&other)
                    .to_string_lossy()
                    .into_owned()
            };
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 2);
            let s = ctx.create_string(&resolved);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(
        path,
        "resolve",
        "(Ljava/nio/file/Path;)Ljava/nio/file/Path;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let base = match ctx.get_field(this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let other = if let Some(Value::Object(Some(o))) = args.get(1) {
                match ctx.get_field(*o, 0) {
                    Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                    _ => String::new(),
                }
            } else {
                String::new()
            };
            let resolved = if jarfs_decode(&base).is_some() || jarfs_decode(&other).is_some() {
                p57_resolve_paths(&base, &other)
            } else {
                std::path::Path::new(&base)
                    .join(&other)
                    .to_string_lossy()
                    .into_owned()
            };
            let p = alloc_concurrent_synthetic(ctx, "java/nio/file/Path", 2);
            let s = ctx.create_string(&resolved);
            ctx.set_field(p, 0, Value::Object(Some(s)));
            Ok(Some(Value::Object(Some(p))))
        },
    );
    r.register(path, "getNameCount", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let path_str = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => return Ok(Some(Value::Int(0))),
        };
        let entry = vfs_decode(&path_str).map(|(_, _, e)| e).unwrap_or(path_str);
        // keycloak-15: count name elements after the (explicitly parsed) Windows
        // drive/UNC root, not std::path components (which mis-count `C:` as a name).
        let count = p57_parse_win_root(&entry).1.len() as i32;
        Ok(Some(Value::Int(count.max(0))))
    });
    r.set_category(__prev_cat);
}

// URI/URL already fully implemented in earlier phases — no additions needed
pub(crate) fn register_p61_net(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // NetworkInterface = 5-field synthetic (name=0, displayName=1, addresses=2, index=3, flags=4)
    // flags: bit 0 = up, bit 1 = loopback, bit 2 = supportsMulticast
    let ni = "java/net/NetworkInterface";

    // NOTE: `getNetworkInterfaces` is intentionally NOT registered as a
    // synthetic native in real-JDK mode. See the long comment in
    // `register_re8_network_interface` (net_phase_e.rs) for details. The
    // real JDK Java method calls native `getAll()` (returns empty) which
    // produces a SocketException that callers handle. Returning synthetic
    // NetworkInterface objects here breaks downstream `getInetAddresses()`
    // because the real JDK reads field slots we don't populate.

    r.register(
        ni,
        "getByName",
        "(Ljava/lang/String;)Ljava/net/NetworkInterface;",
        |ctx, args| {
            let name_ref = obj_arg(args, 1)?;
            let name = ctx.read_string(name_ref).unwrap_or_default();
            let interfaces = p61_build_network_interfaces(ctx);
            for iface in &interfaces {
                if let Value::Object(Some(s)) = ctx.get_field(*iface, 0) {
                    if ctx.read_string(s).as_deref() == Some(&name) {
                        return Ok(Some(Value::Object(Some(*iface))));
                    }
                }
            }
            Ok(Some(Value::Object(None)))
        },
    );

    r.register(
        ni,
        "getByInetAddress",
        "(Ljava/net/InetAddress;)Ljava/net/NetworkInterface;",
        |ctx, args| {
            let addr_ref = obj_arg(args, 1)?;
            let addr_str = match ctx.get_field(addr_ref, 1) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            };
            let interfaces = p61_build_network_interfaces(ctx);
            for iface in &interfaces {
                if let Value::Object(Some(addrs)) = ctx.get_field(*iface, 2) {
                    let len = ctx.array_length(addrs);
                    for i in 0..len {
                        if let Value::Object(Some(ia)) = ctx.get_array_element(addrs, i) {
                            if let Value::Object(Some(s)) = ctx.get_field(ia, 1) {
                                if ctx.read_string(s).as_deref() == Some(&addr_str) {
                                    return Ok(Some(Value::Object(Some(*iface))));
                                }
                            }
                        }
                    }
                }
            }
            Ok(Some(Value::Object(None)))
        },
    );

    r.register(ni, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ni, "getDisplayName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(
        ni,
        "getInetAddresses",
        "()Ljava/util/Enumeration;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let addrs = ctx.get_field(this, 2);
            // Concrete `Enumeration$Impl`, not the bare `Enumeration` interface.
            let enum_obj = alloc_concurrent_synthetic(ctx, "java/util/Enumeration$Impl", 2);
            match addrs {
                Value::Object(Some(a)) => {
                    ctx.set_field(enum_obj, 0, Value::Object(Some(a)));
                    ctx.set_field(enum_obj, 1, Value::Int(0));
                }
                _ => {
                    let empty = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
                    ctx.set_field(enum_obj, 0, Value::Object(Some(empty)));
                    ctx.set_field(enum_obj, 1, Value::Int(0));
                }
            }
            Ok(Some(Value::Object(Some(enum_obj))))
        },
    );
    r.register(ni, "getIndex", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });
    r.register(ni, "isUp", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 1 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "isLoopback", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 2 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "supportsMulticast", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let flags = ctx.get_field(this, 4).as_int().unwrap_or(0);
        Ok(Some(Value::Int(if flags & 4 != 0 { 1 } else { 0 })))
    });
    r.register(ni, "isPointToPoint", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(ni, "isVirtual", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    r.register(ni, "getHardwareAddress", "()[B", |ctx, _args| {
        // Return a dummy MAC address (00:00:00:00:00:00) — real MAC requires platform APIs
        let mac = ctx.new_array(cratonvm_types::ArrayElementType::Byte, 6);
        for i in 0..6 {
            ctx.set_array_element(mac, i, Value::Int(0));
        }
        Ok(Some(Value::Object(Some(mac))))
    });
    r.register(ni, "getMTU", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(1500))) // standard ethernet MTU
    });
    r.register(
        ni,
        "getSubInterfaces",
        "()Ljava/util/Enumeration;",
        |ctx, _args| {
            // Concrete `Enumeration$Impl`, not the bare `Enumeration` interface.
            let enum_obj = alloc_concurrent_synthetic(ctx, "java/util/Enumeration$Impl", 2);
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            ctx.set_field(enum_obj, 0, Value::Object(Some(arr)));
            ctx.set_field(enum_obj, 1, Value::Int(0));
            Ok(Some(Value::Object(Some(enum_obj))))
        },
    );
    r.register(
        ni,
        "getParent",
        "()Ljava/net/NetworkInterface;",
        |_ctx, _args| Ok(Some(Value::Object(None))),
    );
    r.register(ni, "equals", "(Ljava/lang/Object;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let other = obj_arg(args, 1)?;
        let n1 = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let n2 = match ctx.get_field(other, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        Ok(Some(Value::Int(if n1 == n2 { 1 } else { 0 })))
    });
    r.register(ni, "hashCode", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let mut hash: i32 = 0;
        for b in name.bytes() {
            hash = hash.wrapping_mul(31).wrapping_add(b as i32);
        }
        Ok(Some(Value::Int(hash)))
    });
    r.register(ni, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let name = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let s = ctx.create_string(&format!("name:{}", name));
        Ok(Some(Value::Object(Some(s))))
    });
    r.set_category(__prev_cat);
}

/// Build the list of NetworkInterface synthetic objects for this host.
/// Returns loopback + primary interface (resolved via hostname DNS).
fn p61_build_network_interfaces(ctx: &mut dyn NativeContext) -> Vec<ObjectRef> {
    let mut result = Vec::new();

    // 1. Loopback interface
    let lo = alloc_concurrent_synthetic(ctx, "java/net/NetworkInterface", 5);
    let lo_name = ctx.create_string("lo");
    let lo_display = ctx.create_string("Loopback Interface");
    ctx.set_field(lo, 0, Value::Object(Some(lo_name)));
    ctx.set_field(lo, 1, Value::Object(Some(lo_display)));
    // InetAddress for 127.0.0.1 — `alloc_inet_address_external` records
    // host/IP in the `net_phase_e` side table AND populates a real-JDK
    // `InetAddress$InetAddressHolder` (instance slot 0 is the typed
    // `holder` reference field, never a bare String). This is the object
    // Hazelcast's `DefaultAddressPicker` enumerates via
    // `NetworkInterface.getInetAddresses()` then calls `.getHostName()` on.
    let lo_addr = crate::net_phase_e::alloc_inet_address_external(ctx, "localhost", "127.0.0.1");
    let lo_addrs = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 1);
    ctx.set_array_element(lo_addrs, 0, Value::Object(Some(lo_addr)));
    ctx.set_field(lo, 2, Value::Object(Some(lo_addrs)));
    ctx.set_field(lo, 3, Value::Int(1)); // index
    ctx.set_field(lo, 4, Value::Int(0b111)); // up + loopback + multicast
    result.push(lo);

    // 2. Primary interface — resolve hostname to get primary IP. Use the
    //    portable hostname/IP helpers so this code path agrees with what
    //    `InetAddress.getLocalHost` returns and works identically on Linux,
    //    macOS, and Windows. (NEW-2 / C7)
    let hostname = crate::resolve_real_hostname();
    let primary_ip = crate::resolve_primary_ipv4(&hostname);

    if primary_ip != "127.0.0.1" {
        let eth = alloc_concurrent_synthetic(ctx, "java/net/NetworkInterface", 5);
        let eth_name = ctx.create_string("eth0");
        let eth_display = ctx.create_string("Primary Network Interface");
        ctx.set_field(eth, 0, Value::Object(Some(eth_name)));
        ctx.set_field(eth, 1, Value::Object(Some(eth_display)));
        let eth_addr = crate::net_phase_e::alloc_inet_address_external(ctx, &hostname, &primary_ip);
        let eth_addrs = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 1);
        ctx.set_array_element(eth_addrs, 0, Value::Object(Some(eth_addr)));
        ctx.set_field(eth, 2, Value::Object(Some(eth_addrs)));
        ctx.set_field(eth, 3, Value::Int(2)); // index
        ctx.set_field(eth, 4, Value::Int(0b101)); // up + multicast (not loopback)
        result.push(eth);
    }

    result
}

// =============================================================================
// Phase 62: CharBuffer, Time expansion (MonthDay/YearMonth/Year), NumberFormat
//           factories, Collectors expansion, NavigableMap/Set completion,
//           AbstractMap entries, StampedLock, ZipEntry
// =============================================================================

pub(crate) fn register_phase62_natives(registry: &mut NativeMethodRegistry) {
    let __prev_cat = registry.current_category();
    registry.set_category(cratonvm_native_api::NativeKind::Bridge);
    register_p62_char_buffer(registry);
    register_p62_time_expansion(registry);
    register_p62_format_factories(registry);
    register_p62_navigable_expansion(registry);
    register_p62_abstract_map_entries(registry);
    // StampedLock is registered separately with the side-table implementation
    // used by real JDK lock-view bytecode. The older p62 2-field shim is
    // intentionally not installed in the essential path, because mixing its
    // `writeLock()` with the side-table `unstampedUnlock*` methods makes
    // `StampedLock$WriteLockView.unlock()` throw spuriously.
    register_p62_zip_entry(registry);
    registry.set_category(__prev_cat);
}

// =============================================================================
// java.nio.CharBuffer = 5-field (array=0 char[], pos=1, limit=2, capacity=3, mark=4)
// =============================================================================

const CB_FIELD_ARRAY: usize = 0;
const CB_FIELD_POS: usize = 1;
const CB_FIELD_LIMIT: usize = 2;
const CB_FIELD_CAPACITY: usize = 3;
const CB_FIELD_MARK: usize = 4;

/// Initialise a freshly-allocated synthetic CharBuffer so BOTH the
/// indexed-slot layout (used by our own natives) AND the real-JDK
/// `hb` / `position` / `limit` / `capacity` / `mark` / `offset` /
/// `isReadOnly` fields (used by JDK bytecode that wasn't overridden)
/// reference the same backing char[]. Without the by-name writes the
/// JDK bytecode for `hasArray` / `array` / `subSequence` reads a null
/// `hb` (uninitialised real-JDK field) and throws "no backing array"
/// — observed on icu4j-68.2 / icu4j-70.1 going through
/// `CharBuffer.subSequence(...).toString()` in `ICUResourceBundleReader.
/// getStringV2`.
pub(crate) fn cb_write_hb(
    ctx: &mut dyn NativeContext,
    buf: ObjectRef,
    arr: ObjectRef,
    len_chars: i32,
) {
    // Real-JDK field names: `hb` (char[]), `offset` (int),
    // `isReadOnly` (boolean) on CharBuffer; `mark` / `position` /
    // `limit` / `capacity` (int) on Buffer.
    ctx.set_field_by_name(buf, "hb", Value::Object(Some(arr)));
    ctx.set_field_by_name(buf, "offset", Value::Int(0));
    ctx.set_field_by_name(buf, "isReadOnly", Value::Int(0));
    ctx.set_field_by_name(buf, "position", Value::Int(0));
    ctx.set_field_by_name(buf, "limit", Value::Int(len_chars));
    ctx.set_field_by_name(buf, "capacity", Value::Int(len_chars));
    ctx.set_field_by_name(buf, "mark", Value::Int(-1));
    // Synthetic-mode indexed fallback (older callers).
    ctx.set_field(buf, CB_FIELD_ARRAY, Value::Object(Some(arr)));
    ctx.set_field(buf, CB_FIELD_POS, Value::Int(0));
    ctx.set_field(buf, CB_FIELD_LIMIT, Value::Int(len_chars));
    ctx.set_field(buf, CB_FIELD_CAPACITY, Value::Int(len_chars));
    ctx.set_field(buf, CB_FIELD_MARK, Value::Int(-1));
}

/// Read the backing char[] from a CharBuffer, honouring both the
/// real-JDK `hb` field and the synthetic indexed slot.
fn cb_read_hb(ctx: &dyn NativeContext, buf: ObjectRef) -> Option<ObjectRef> {
    match ctx.get_field_by_name(buf, "hb") {
        Value::Object(Some(a)) => Some(a),
        _ => match ctx.get_field(buf, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => Some(a),
            _ => None,
        },
    }
}

/// Plain CharBuffer/HeapCharBuffer/StringCharBuffer instances have no
/// independent byte-order concept of their own (real `HeapCharBuffer.order()`
/// just returns the platform's native order); this mirrors the same
/// convention already used by `ByteOrder.nativeOrder()`
/// (`servlet.rs::register_s2_byteorder`) — 0 = BIG_ENDIAN, 1 = LITTLE_ENDIAN.
///
/// Note: `ByteBuffer.asCharBuffer()` (`servlet.rs::s2_bb_as_char_buffer`)
/// allocates its returned view under this same plain `java/nio/CharBuffer`
/// class name (not one of the `ByteBufferAsCharBuffer{B,L,RB,RL}` subclasses)
/// and separately stashes the source ByteBuffer's order in an indexed slot —
/// that slot is not read here, so an `asCharBuffer()` view built over a
/// non-native-order source ByteBuffer will report native order rather than
/// the source's actual order from this native. That's a narrower, pre-existing
/// gap in `s2_bb_as_char_buffer`'s view-class choice, independent of the
/// AbstractMethodError this registration fixes (real HeapCharBuffer/wrap/
/// allocate paths, which is what the affected Spring Boot classes exercise).
#[inline]
fn cb_native_order(_ctx: &dyn NativeContext, _buf: ObjectRef) -> i32 {
    if cfg!(target_endian = "big") {
        0
    } else {
        1
    }
}

pub(crate) fn register_p62_char_buffer(r: &mut NativeMethodRegistry) {
    use crate::servlet::s2_byte_order_object;
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let cb = "java/nio/CharBuffer";
    r.register(cb, "allocate", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let cap = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 16,
        };
        let buf = p62_alloc_char_buffer(ctx, cap.max(0) as usize);
        Ok(Some(Value::Object(Some(buf))))
    });
    r.register(cb, "wrap", "([C)Ljava/nio/CharBuffer;", |ctx, args| {
        let arr = match args.first() {
            Some(Value::Object(Some(a))) => *a,
            _ => return Ok(Some(Value::Object(None))),
        };
        let len = ctx.array_length(arr);
        // Pin across the buffer alloc below — a moving young GC there would
        // relocate the backing array (native stale-local family).
        let arr_pin = ctx.pin_native_root(arr);
        let buf = alloc_concurrent_synthetic(ctx, "java/nio/CharBuffer", 5);
        let arr = ctx.read_native_pin(arr_pin, arr);
        ctx.unpin_native_roots(arr_pin);
        cb_write_hb(ctx, buf, arr, len as i32);
        Ok(Some(Value::Object(Some(buf))))
    });
    r.register(
        cb,
        "wrap",
        "(Ljava/lang/CharSequence;)Ljava/nio/CharBuffer;",
        |ctx, args| {
            // The arg is any CharSequence, not necessarily a String. For a
            // real String `read_string` works; for other implementations
            // (e.g. Tomcat's `CharChunk`, StringBuilder, CharBuffer) it
            // returns None/empty, so fall back to a virtual `toString()`.
            // Without this fallback `CharBuffer.wrap(charChunk)` produced an
            // empty buffer, so `MessageBytes.toBytes` (which does
            // `encoder.encode(CharBuffer.wrap(charC))`) encoded nothing —
            // 144 Tomcat MessageBytes-conversion failures.
            let s = match args.first() {
                Some(Value::Object(Some(s))) => {
                    let direct = ctx.read_string(*s).unwrap_or_default();
                    if !direct.is_empty() {
                        direct
                    } else {
                        match ctx.invoke_virtual(*s, "toString", "()Ljava/lang/String;", &[]) {
                            Ok(Some(Value::Object(Some(strref)))) => {
                                ctx.read_string(strref).unwrap_or_default()
                            }
                            _ => direct,
                        }
                    }
                }
                _ => String::new(),
            };
            let chars: Vec<u16> = s.encode_utf16().collect();
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Char, chars.len());
            for (i, &ch) in chars.iter().enumerate() {
                ctx.set_array_element(arr, i, Value::Int(ch as i32));
            }
            // Pin across the buffer alloc below — a moving young GC there
            // would relocate the backing array (native stale-local family).
            let arr_pin = ctx.pin_native_root(arr);
            let buf = alloc_concurrent_synthetic(ctx, "java/nio/CharBuffer", 5);
            let arr = ctx.read_native_pin(arr_pin, arr);
            ctx.unpin_native_roots(arr_pin);
            cb_write_hb(ctx, buf, arr, chars.len() as i32);
            Ok(Some(Value::Object(Some(buf))))
        },
    );
    // hasArray()Z — JDK bytecode reads `hb != null && !isReadOnly`.
    // Mirror that with a robust slot/name lookup so synthetic-mode
    // CharBuffers (where slot 0 may have been overwritten by
    // descriptor-coerced int writes against Buffer.mark) still
    // report true. Without this, icu4j's `b16BitUnits.subSequence(
    // start, end).toString()` reads a null `hb` and throws
    // `IllegalStateException("CharBuffer has no backing array")`.
    r.register(cb, "hasArray", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(Value::Int(if cb_read_hb(ctx, this).is_some() {
            1
        } else {
            0
        })))
    });
    // CharBuffer.isReadOnly()/isDirect() are abstract in the real JDK (each
    // concrete Heap/Direct/View subclass overrides them) — every OTHER typed
    // view buffer (Int/Long/Short/Float/DoubleBuffer) gets these registered
    // directly on its own class, but CharBuffer was missing from that list.
    // Objects allocated straight against the literal `java/nio/CharBuffer`
    // class (this file's `wrap`/`allocate` above use it directly rather than
    // a Heap-prefixed subclass) then hit the abstract declaration on
    // `isReadOnly()` — "AbstractMethodError: java/nio/Buffer.isReadOnly()Z
    // has no Code attribute" (CratonVM resolves the abstract method all the
    // way up to `Buffer` because neither `CharBuffer` nor `Buffer` had a
    // native registered) — killing any caller whose real-JDK bytecode reads
    // `hasArray()`/`isReadOnly()` on a CharBuffer (e.g. Lucene's vector codec
    // tests decoding index metadata strings).
    r.register(cb, "isReadOnly", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(Value::Int(
            match ctx.get_field_by_name(this, "isReadOnly") {
                Value::Int(v) => v,
                _ => 0,
            },
        )))
    });
    r.register(cb, "isDirect", "()Z", |_ctx, _args| Ok(Some(Value::Int(0))));
    // order()Ljava/nio/ByteOrder; — abstract on CharBuffer, like isReadOnly/
    // isDirect above; every concrete leaf subclass overrides it in real
    // OpenJDK. CratonVM never registered a native anywhere in the CharBuffer
    // hierarchy, so any first-use call (real-JDK bytecode resolves the
    // abstract declaration with no override) throws
    // "AbstractMethodError: java/nio/CharBuffer.order()Ljava/nio/ByteOrder;
    // has no Code attribute" — hit by ICU4X's `UCharacterProperty.<clinit>`
    // reading Unicode property data via `CharBuffer.get(int[])`, which
    // transitively poisons `java.net.IDN.<clinit>` (the first caller to ever
    // exercise this path) for the rest of the process. Plain `CharBuffer`/
    // `HeapCharBuffer`/`StringCharBuffer` report the platform's native byte
    // order, matching real `HeapCharBuffer.order()`; the four
    // `ByteBufferAsCharBuffer{B,L,RB,RL}` view classes encode their
    // endianness in the class-name suffix (B/RB = big, L/RL = little),
    // matching real JDK's per-view-class `order()` overrides.
    r.register(cb, "order", "()Ljava/nio/ByteOrder;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ord = cb_native_order(ctx, this);
        Ok(Some(Value::Object(Some(s2_byte_order_object(ctx, ord)))))
    });
    fn cb_order_big(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
        use crate::servlet::s2_byte_order_object;
        Ok(Some(Value::Object(Some(s2_byte_order_object(ctx, 0)))))
    }
    fn cb_order_little(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
        use crate::servlet::s2_byte_order_object;
        Ok(Some(Value::Object(Some(s2_byte_order_object(ctx, 1)))))
    }
    for subclass in [
        "java/nio/ByteBufferAsCharBufferB",
        "java/nio/ByteBufferAsCharBufferRB",
    ] {
        r.register(subclass, "order", "()Ljava/nio/ByteOrder;", cb_order_big);
    }
    for subclass in [
        "java/nio/ByteBufferAsCharBufferL",
        "java/nio/ByteBufferAsCharBufferRL",
    ] {
        r.register(subclass, "order", "()Ljava/nio/ByteOrder;", cb_order_little);
    }
    r.register(cb, "arrayOffset", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        match ctx.get_field_by_name(this, "offset") {
            Value::Int(v) => Ok(Some(Value::Int(v))),
            _ => Ok(Some(Value::Int(0))),
        }
    });
    // toString(II) / toString() — abstract on CharBuffer; subSequence and
    // wrap return synthetic instances with class `java/nio/CharBuffer`
    // itself, so the default `toString()` body (which calls
    // `toString(position(), limit())` on this) hits an abstract method
    // and throws AbstractMethodError. ICUBinary.getString uses exactly
    // this pattern (`bytes.asCharBuffer().subSequence(0,len).toString()`)
    // during ICU normalization data load, which blocks ICU clinit and
    // cascades into Jetty `Main.processCommandLine` NPE.
    fn cb_to_string_range(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Object(None))),
        };
        let start = args.get(1).and_then(|v| v.as_int()).unwrap_or(0);
        let end = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
        let cur_pos = match ctx.get_field_by_name(this, "position") {
            Value::Int(v) => v,
            _ => match ctx.get_field(this, CB_FIELD_POS) {
                Value::Int(v) => v,
                _ => 0,
            },
        };
        let cur_off = match ctx.get_field_by_name(this, "offset") {
            Value::Int(v) => v,
            _ => 0,
        };
        // StringCharBuffer has no `hb`; it stores the wrapped CharSequence in
        // `str` and uses the same position/limit/offset coordinates as the
        // JDK bytecode. This is reached by Netty's
        // `CharBuffer.wrap(String,start,end).toString()` cookie path.
        let cid = ctx.class_id_of_object(this);
        let cname = ctx.class_name_of_id(cid).unwrap_or_default();
        if cname == "java/nio/StringCharBuffer" {
            let str_obj = match ctx.get_field_by_name(this, "str") {
                Value::Object(Some(o)) => o,
                _ => return Ok(Some(Value::Object(Some(ctx.create_string(""))))),
            };
            let text = ctx.read_string(str_obj).unwrap_or_default();
            let units: Vec<u16> = text.encode_utf16().collect();
            // StringCharBuffer.toString(int,int) receives absolute buffer
            // indexes (CharBuffer.toString() calls it with position..limit),
            // and StringCharBuffer then adds only `offset` before slicing
            // the wrapped CharSequence. Do not add current position again.
            let abs_start = cur_off + start;
            let abs_end = cur_off + end;
            let len = units.len() as i32;
            let s_lo = abs_start.max(0).min(len);
            let s_hi = abs_end.max(s_lo).min(len);
            let out = String::from_utf16_lossy(&units[s_lo as usize..s_hi as usize]);
            return Ok(Some(Value::Object(Some(ctx.create_string(&out)))));
        }
        let arr = match cb_read_hb(ctx, this) {
            Some(a) => a,
            None => return Ok(Some(Value::Object(Some(ctx.create_string(""))))),
        };
        // CharBuffer.toString(int start, int end) reads start..end (exclusive)
        // RELATIVE to the current position — see HeapCharBuffer.toString.
        let abs_start = cur_off + cur_pos + start;
        let abs_end = cur_off + cur_pos + end;
        let arr_len = ctx.array_length(arr) as i32;
        let s_lo = abs_start.max(0).min(arr_len);
        let s_hi = abs_end.max(s_lo).min(arr_len);
        let mut chars: Vec<u16> = Vec::with_capacity((s_hi - s_lo) as usize);
        for i in s_lo..s_hi {
            if let Value::Int(v) = ctx.get_array_element(arr, i as usize) {
                chars.push(v as u16);
            }
        }
        let s: String = String::from_utf16_lossy(&chars);
        Ok(Some(Value::Object(Some(ctx.create_string(&s)))))
    }
    r.register(cb, "toString", "(II)Ljava/lang/String;", cb_to_string_range);
    // Concrete CharBuffer subclasses inherit our toString(II) only when the
    // VM's vtable-lookup walks the super-class native registry. The
    // ByteBufferAs*CharBuffer family and HeapCharBuffer are what
    // `ByteBuffer.asCharBuffer()` returns in real-JDK mode, so registering
    // directly on each ensures dispatch hits us regardless of how vtable
    // resolution handles abstract-in-base + native-on-base.
    for subclass in [
        "java/nio/ByteBufferAsCharBufferB",
        "java/nio/ByteBufferAsCharBufferL",
        "java/nio/ByteBufferAsCharBufferRB",
        "java/nio/ByteBufferAsCharBufferRL",
        "java/nio/HeapCharBuffer",
        "java/nio/HeapCharBufferR",
        "java/nio/StringCharBuffer",
    ] {
        r.register(
            subclass,
            "toString",
            "(II)Ljava/lang/String;",
            cb_to_string_range,
        );
    }
    r.register(cb, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Object(None))),
        };
        let pos = match ctx.get_field_by_name(this, "position") {
            Value::Int(v) => v,
            _ => match ctx.get_field(this, CB_FIELD_POS) {
                Value::Int(v) => v,
                _ => 0,
            },
        };
        let lim = match ctx.get_field_by_name(this, "limit") {
            Value::Int(v) => v,
            _ => match ctx.get_field(this, CB_FIELD_LIMIT) {
                Value::Int(v) => v,
                _ => pos,
            },
        };
        // toString() is documented as toString(position(), limit()). For
        // synthetic/heap buffers our `cb_to_string_range` historically treats
        // the range as relative, so keep the old 0..remaining call here.
        let args2 = [
            Value::Object(Some(this)),
            Value::Int(0),
            Value::Int(lim - pos),
        ];
        cb_to_string_range(ctx, &args2)
    });
    r.register(
        "java/nio/StringCharBuffer",
        "toString",
        "()Ljava/lang/String;",
        |ctx, args| {
            let this = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let pos = match ctx.get_field_by_name(this, "position") {
                Value::Int(v) => v,
                _ => 0,
            };
            let lim = match ctx.get_field_by_name(this, "limit") {
                Value::Int(v) => v,
                _ => pos,
            };
            let args2 = [Value::Object(Some(this)), Value::Int(pos), Value::Int(lim)];
            cb_to_string_range(ctx, &args2)
        },
    );
    // subSequence(II)Ljava/nio/CharBuffer; — abstract on CharBuffer, so
    // an unbacked synthetic instance would AbstractMethodError. Allocate
    // a fresh CharBuffer with the same backing array and adjusted
    // position/limit (start..end relative to current position).
    r.register(
        cb,
        "subSequence",
        "(II)Ljava/nio/CharBuffer;",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let start = args.get(1).and_then(|v| v.as_int()).unwrap_or(0);
            let end = args.get(2).and_then(|v| v.as_int()).unwrap_or(0);
            let arr = match cb_read_hb(ctx, this) {
                Some(a) => a,
                None => {
                    return Err(RuntimeError::IllegalStateException {
                        message: "CharBuffer.subSequence: no backing array".into(),
                    }
                    .into())
                }
            };
            let cur_pos = match ctx.get_field_by_name(this, "position") {
                Value::Int(v) => v,
                _ => match ctx.get_field(this, CB_FIELD_POS) {
                    Value::Int(v) => v,
                    _ => 0,
                },
            };
            let cur_off = match ctx.get_field_by_name(this, "offset") {
                Value::Int(v) => v,
                _ => 0,
            };
            let new_pos = cur_pos + start;
            let new_lim = cur_pos + end;
            // Allocate a fresh HeapCharBuffer pointing at the same char[]
            // — JDK's HeapCharBuffer.subSequence does the same.
            // Pin across the buffer alloc below — a moving young GC there
            // would relocate the backing array (native stale-local family).
            let arr_pin = ctx.pin_native_root(arr);
            let buf = alloc_concurrent_synthetic(ctx, "java/nio/HeapCharBuffer", 5);
            let arr = ctx.read_native_pin(arr_pin, arr);
            ctx.unpin_native_roots(arr_pin);
            ctx.set_field_by_name(buf, "hb", Value::Object(Some(arr)));
            ctx.set_field_by_name(buf, "offset", Value::Int(cur_off));
            ctx.set_field_by_name(buf, "isReadOnly", Value::Int(0));
            ctx.set_field_by_name(buf, "position", Value::Int(new_pos));
            ctx.set_field_by_name(buf, "limit", Value::Int(new_lim));
            ctx.set_field_by_name(buf, "capacity", Value::Int(new_lim));
            ctx.set_field_by_name(buf, "mark", Value::Int(-1));
            ctx.set_field(buf, CB_FIELD_ARRAY, Value::Object(Some(arr)));
            ctx.set_field(buf, CB_FIELD_POS, Value::Int(new_pos));
            ctx.set_field(buf, CB_FIELD_LIMIT, Value::Int(new_lim));
            ctx.set_field(buf, CB_FIELD_CAPACITY, Value::Int(new_lim));
            ctx.set_field(buf, CB_FIELD_MARK, Value::Int(-1));
            Ok(Some(Value::Object(Some(buf))))
        },
    );
    r.register(cb, "get", "()C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if pos >= lim {
            return Err(RuntimeError::BufferUnderflowException.into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        let ch = ctx.get_array_element(arr, pos as usize);
        ctx.set_field(this, CB_FIELD_POS, Value::Int(pos + 1));
        Ok(Some(ch))
    });
    r.register(cb, "get", "(I)C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let idx = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if idx < 0 || idx >= lim {
            return Err(RuntimeError::IllegalArgumentException {
                message: format!("index: {idx}"),
            }
            .into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        Ok(Some(ctx.get_array_element(arr, idx as usize)))
    });
    r.register(cb, "put", "(C)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let ch = args.get(1).copied().unwrap_or(Value::Int(0));
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        if pos >= lim {
            return Err(RuntimeError::BufferOverflowException.into());
        }
        let arr = match ctx.get_field(this, CB_FIELD_ARRAY) {
            Value::Object(Some(a)) => a,
            _ => {
                return Err(RuntimeError::IllegalStateException {
                    message: "no backing array".into(),
                }
                .into())
            }
        };
        ctx.set_array_element(arr, pos as usize, ch);
        ctx.set_field(this, CB_FIELD_POS, Value::Int(pos + 1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "flip", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(pos));
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "clear", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cap = match ctx.get_field(this, CB_FIELD_CAPACITY) {
            Value::Int(v) => v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(cap));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "rewind", "()Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, CB_FIELD_POS, Value::Int(0));
        ctx.set_field(this, CB_FIELD_MARK, Value::Int(-1));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "remaining", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int((lim - pos).max(0))))
    });
    r.register(cb, "hasRemaining", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field(this, CB_FIELD_POS) {
            Value::Int(v) => v,
            _ => 0,
        };
        let lim = match ctx.get_field(this, CB_FIELD_LIMIT) {
            Value::Int(v) => v,
            _ => 0,
        };
        Ok(Some(Value::Int(if pos < lim { 1 } else { 0 })))
    });
    r.register(cb, "position", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_POS)))
    });
    r.register(cb, "position", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let new_pos = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_POS, Value::Int(new_pos));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "limit", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_LIMIT)))
    });
    r.register(cb, "limit", "(I)Ljava/nio/CharBuffer;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let new_lim = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 0,
        };
        ctx.set_field(this, CB_FIELD_LIMIT, Value::Int(new_lim));
        Ok(Some(Value::Object(Some(this))))
    });
    r.register(cb, "capacity", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, CB_FIELD_CAPACITY)))
    });
    r.register(cb, "array", "()[C", |ctx, args| {
        let this = obj_arg(args, 0)?;
        match cb_read_hb(ctx, this) {
            Some(a) => Ok(Some(Value::Object(Some(a)))),
            None => Err(RuntimeError::IllegalStateException {
                message: "CharBuffer.array: no backing array".into(),
            }
            .into()),
        }
    });
    r.register(cb, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let pos = match ctx.get_field_by_name(this, "position") {
            Value::Int(v) => v as usize,
            _ => match ctx.get_field(this, CB_FIELD_POS) {
                Value::Int(v) => v as usize,
                _ => 0,
            },
        };
        let lim = match ctx.get_field_by_name(this, "limit") {
            Value::Int(v) => v as usize,
            _ => match ctx.get_field(this, CB_FIELD_LIMIT) {
                Value::Int(v) => v as usize,
                _ => 0,
            },
        };
        let off = match ctx.get_field_by_name(this, "offset") {
            Value::Int(v) => v as usize,
            _ => 0,
        };
        let arr = match cb_read_hb(ctx, this) {
            Some(a) => a,
            None => {
                let s = ctx.create_string("");
                return Ok(Some(Value::Object(Some(s))));
            }
        };
        let mut chars = Vec::new();
        for i in pos..lim {
            if let Value::Int(ch) = ctx.get_array_element(arr, i + off) {
                chars.push(ch as u16);
            }
        }
        let text = String::from_utf16_lossy(&chars);
        let s = ctx.create_string(&text);
        Ok(Some(Value::Object(Some(s))))
    });

    // Also register under Buffer parent
    let buf = "java/nio/Buffer";
    r.register(buf, "position", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1))) // pos field
    });
    r.register(buf, "limit", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    r.register(buf, "capacity", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 3)))
    });
    r.set_category(__prev_cat);
}

fn p62_alloc_char_buffer(ctx: &mut dyn NativeContext, cap: usize) -> ObjectRef {
    let arr = ctx.new_array(cratonvm_types::ArrayElementType::Char, cap);
    // Use HeapCharBuffer (concrete) not CharBuffer (abstract) so real-JDK
    // bytecode methods like compact() dispatch correctly.
    // Pin across the buffer alloc below — a moving young GC there would
    // relocate the backing array (native stale-local family).
    let arr_pin = ctx.pin_native_root(arr);
    let buf = alloc_concurrent_synthetic(ctx, "java/nio/HeapCharBuffer", 5);
    let arr = ctx.read_native_pin(arr_pin, arr);
    ctx.unpin_native_roots(arr_pin);
    cb_write_hb(ctx, buf, arr, cap as i32);
    buf
}

// =============================================================================
// java.time expansion — MonthDay, YearMonth, Year
// =============================================================================

pub(crate) fn register_p62_time_expansion(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // --- Year = 1-field (year=0 Int) ---
    let yr = "java/time/Year";
    r.register(yr, "of", "(I)Ljava/time/Year;", |ctx, args| {
        let y = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "now", "()Ljava/time/Year;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(2026));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "getValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(yr, "isLeap", "()Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 1 } else { 0 })))
    });
    r.register(yr, "isLeap", "(J)Z", |_ctx, args| {
        let y = match args.first() {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 1 } else { 0 })))
    });
    r.register(yr, "length", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let leap = (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
        Ok(Some(Value::Int(if leap { 366 } else { 365 })))
    });
    r.register(yr, "plusYears", "(J)Ljava/time/Year;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let add = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y + add));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "minusYears", "(J)Ljava/time/Year;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let sub = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/Year", 1);
        ctx.set_field(obj, 0, Value::Int(y - sub));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(yr, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let s = ctx.create_string(&format!("{y}"));
        Ok(Some(Value::Object(Some(s))))
    });
    r.register(yr, "compareTo", "(Ljava/time/Year;)I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y1 = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let y2 = if let Some(Value::Object(Some(o))) = args.get(1) {
            match ctx.get_field(*o, 0) {
                Value::Int(v) => v,
                _ => 0,
            }
        } else {
            0
        };
        Ok(Some(Value::Int(y1.cmp(&y2) as i32)))
    });

    // --- YearMonth = 2-field (year=0, month=1 Int 1-12) ---
    let ym = "java/time/YearMonth";
    r.register(ym, "of", "(II)Ljava/time/YearMonth;", |ctx, args| {
        let y = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let m = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(y));
        ctx.set_field(obj, 1, Value::Int(m));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "now", "()Ljava/time/YearMonth;", |ctx, _args| {
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(2026));
        ctx.set_field(obj, 1, Value::Int(2));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "getYear", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(ym, "getMonthValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(ym, "lengthOfMonth", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 2000,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let days = p62_days_in_month(y, m);
        Ok(Some(Value::Int(days)))
    });
    r.register(ym, "plusMonths", "(J)Ljava/time/YearMonth;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let add = match args.get(1) {
            Some(Value::Long(v)) => *v as i32,
            _ => 0,
        };
        let total = (y * 12 + (m - 1)) + add;
        let new_y = total.div_euclid(12);
        let new_m = total.rem_euclid(12) + 1;
        let obj = alloc_concurrent_synthetic(ctx, "java/time/YearMonth", 2);
        ctx.set_field(obj, 0, Value::Int(new_y));
        ctx.set_field(obj, 1, Value::Int(new_m));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(ym, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let y = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 0,
        };
        let m = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let s = ctx.create_string(&format!("{y:04}-{m:02}"));
        Ok(Some(Value::Object(Some(s))))
    });

    // --- MonthDay = 2-field (month=0, day=1) ---
    let md = "java/time/MonthDay";
    r.register(md, "of", "(II)Ljava/time/MonthDay;", |ctx, args| {
        let m = match args.first() {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let d = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 1,
        };
        let obj = alloc_concurrent_synthetic(ctx, "java/time/MonthDay", 2);
        ctx.set_field(obj, 0, Value::Int(m));
        ctx.set_field(obj, 1, Value::Int(d));
        Ok(Some(Value::Object(Some(obj))))
    });
    r.register(md, "getMonthValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(md, "getDayOfMonth", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(md, "isValidYear", "(I)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let m = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 1,
        };
        let d = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let y = match args.get(1) {
            Some(Value::Int(v)) => *v,
            _ => 2000,
        };
        let max = p62_days_in_month(y, m);
        Ok(Some(Value::Int(if d <= max { 1 } else { 0 })))
    });
    r.register(md, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let m = match ctx.get_field(this, 0) {
            Value::Int(v) => v,
            _ => 1,
        };
        let d = match ctx.get_field(this, 1) {
            Value::Int(v) => v,
            _ => 1,
        };
        let s = ctx.create_string(&format!("--{m:02}-{d:02}"));
        Ok(Some(Value::Object(Some(s))))
    });
    r.set_category(__prev_cat);
}

fn p62_days_in_month(y: i32, m: i32) -> i32 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => {
            if (y % 4 == 0 && y % 100 != 0) || y % 400 == 0 {
                29
            } else {
                28
            }
        }
        _ => 30,
    }
}

