// =============================================================================
// java.lang.invoke.ConstantBootstraps — Java 11
// =============================================================================

pub(crate) fn register_p70_constant_bootstraps(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    let cb = "java/lang/invoke/ConstantBootstraps";

    // nullConstant — returns null (correct as-is)
    r.register(cb, "nullConstant",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;)Ljava/lang/Object;",
        |_ctx, _args| Ok(Some(Value::Object(None))));

    // primitiveClass — returns the Class object for a primitive type
    r.register(cb, "primitiveClass",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;)Ljava/lang/Class;",
        |ctx, args| {
            // args[1] = name (String), e.g. "int", "long", "double"
            let name = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            // Map primitive name to wrapper class and get the TYPE field
            let wrapper_class = match name.as_str() {
                "int" => "java/lang/Integer",
                "long" => "java/lang/Long",
                "double" => "java/lang/Double",
                "float" => "java/lang/Float",
                "boolean" => "java/lang/Boolean",
                "byte" => "java/lang/Byte",
                "char" => "java/lang/Character",
                "short" => "java/lang/Short",
                "void" => "java/lang/Void",
                _ => return Ok(Some(Value::Object(None))),
            };
            // Get the TYPE static field from the wrapper class
            let class_id = ctx.ensure_class_initialized(wrapper_class)
                .map_err(|e| RuntimeError::IllegalStateException {
                    message: format!("Failed to initialize {}: {:?}", wrapper_class, e),
                })?;
            if let Some(field_idx) = ctx.resolve_field_index(wrapper_class, "TYPE") {
                let type_val = ctx.get_static_field(class_id, field_idx);
                return Ok(Some(type_val));
            }
            // Fallback: return the class mirror itself
            let mirror = ctx.get_class_mirror(class_id);
            Ok(Some(Value::Object(Some(mirror))))
        });

    // enumConstant — look up enum constant by name from the declaring class
    r.register(cb, "enumConstant",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;)Ljava/lang/Enum;",
        |ctx, args| {
            // args[1] = constant name, args[2] = enum Class
            let const_name = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(None))),
            };
            let enum_class = match args.get(2) {
                Some(Value::Object(Some(c))) => *c,
                _ => return Ok(Some(Value::Object(None))),
            };
            let class_id = ctx.class_id_of_object(enum_class);
            let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();
            // Look up the static field with the enum constant name
            if let Some(field_idx) = ctx.resolve_field_index(&class_name, &const_name) {
                let val = ctx.get_static_field(class_id, field_idx);
                return Ok(Some(val));
            }
            Ok(Some(Value::Object(None)))
        });

    // getStaticFinal — read a static final field from a declaring class
    r.register(cb, "getStaticFinal",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;Ljava/lang/Class;)Ljava/lang/Object;",
        |ctx, args| {
            // args[1] = field name, args[3] = declaring class
            let field_name = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => return Ok(Some(Value::Object(None))),
            };
            let declaring = match args.get(3) {
                Some(Value::Object(Some(c))) => *c,
                _ => {
                    // If no declaring class, use the type class (args[2])
                    match args.get(2) {
                        Some(Value::Object(Some(c))) => *c,
                        _ => return Ok(Some(Value::Object(None))),
                    }
                }
            };
            let class_id = ctx.class_id_of_object(declaring);
            let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();
            if let Some(field_idx) = ctx.resolve_field_index(&class_name, &field_name) {
                let val = ctx.get_static_field(class_id, field_idx);
                return Ok(Some(val));
            }
            Ok(Some(Value::Object(None)))
        });

    // invoke — invoke a MethodHandle with provided arguments
    r.register(cb, "invoke",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;Ljava/lang/invoke/MethodHandle;[Ljava/lang/Object;)Ljava/lang/Object;",
        |ctx, args| {
            // args[3] = MethodHandle, args[4] = Object[] arguments
            let mh = match args.get(3) {
                Some(Value::Object(Some(m))) => *m,
                _ => return Ok(Some(Value::Object(None))),
            };
            // Gather arguments from the Object[] array
            let mut invoke_args = vec![Value::Object(Some(mh))];
            if let Some(Value::Object(Some(arr))) = args.get(4) {
                let len = ctx.array_length(*arr);
                for i in 0..len {
                    invoke_args.push(ctx.get_array_element(*arr, i));
                }
            }
            // Try invoking the MethodHandle
            match ctx.invoke_virtual(mh, "invoke", "([Ljava/lang/Object;)Ljava/lang/Object;", &invoke_args) {
                Ok(result) => Ok(result),
                Err(_) => Ok(Some(Value::Object(None))),
            }
        });

    // fieldVarHandle — create a VarHandle for an instance field
    r.register(cb, "fieldVarHandle",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;)Ljava/lang/invoke/VarHandle;",
        |ctx, args| {
            // args[1]=name, args[3]=declaringClass, args[4]=fieldType
            let field_name = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let vh = alloc_concurrent_synthetic(ctx, "java/lang/invoke/VarHandle", 6);
            ctx.set_field(vh, 0, Value::Int(0)); // kind=instance
            let name_s = ctx.create_string(&field_name);
            ctx.set_field(vh, 1, Value::Object(Some(name_s)));
            ctx.set_field(vh, 2, args.get(3).copied().unwrap_or(Value::Object(None))); // declaring class
            ctx.set_field(vh, 3, args.get(4).copied().unwrap_or(Value::Object(None))); // field type
            // Resolve field index for fast access
            if let Some(Value::Object(Some(decl))) = args.get(3) {
                let class_id = ctx.class_id_of_object(*decl);
                let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();
                let idx = ctx.resolve_field_index(&class_name, &field_name).unwrap_or(0);
                ctx.set_field(vh, 4, Value::Int(idx as i32));
            }
            Ok(Some(Value::Object(Some(vh))))
        });

    // staticFieldVarHandle — create a VarHandle for a static field
    r.register(cb, "staticFieldVarHandle",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;Ljava/lang/Class;Ljava/lang/Class;)Ljava/lang/invoke/VarHandle;",
        |ctx, args| {
            let field_name = match args.get(1) {
                Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
                _ => String::new(),
            };
            let vh = alloc_concurrent_synthetic(ctx, "java/lang/invoke/VarHandle", 6);
            ctx.set_field(vh, 0, Value::Int(1)); // kind=static
            let name_s = ctx.create_string(&field_name);
            ctx.set_field(vh, 1, Value::Object(Some(name_s)));
            ctx.set_field(vh, 2, args.get(3).copied().unwrap_or(Value::Object(None)));
            ctx.set_field(vh, 3, args.get(4).copied().unwrap_or(Value::Object(None)));
            if let Some(Value::Object(Some(decl))) = args.get(3) {
                let class_id = ctx.class_id_of_object(*decl);
                let class_name = ctx.class_name_of_id(class_id).unwrap_or_default();
                let idx = ctx.resolve_field_index(&class_name, &field_name).unwrap_or(0);
                ctx.set_field(vh, 4, Value::Int(idx as i32));
                ctx.set_field(vh, 5, Value::Int(class_id.as_u32() as i32));
            }
            Ok(Some(Value::Object(Some(vh))))
        });

    // arrayVarHandle — create a VarHandle for array element access
    r.register(cb, "arrayVarHandle",
        "(Ljava/lang/invoke/MethodHandles$Lookup;Ljava/lang/String;Ljava/lang/Class;Ljava/lang/Class;)Ljava/lang/invoke/VarHandle;",
        |ctx, args| {
            let vh = alloc_concurrent_synthetic(ctx, "java/lang/invoke/VarHandle", 6);
            ctx.set_field(vh, 0, Value::Int(2)); // kind=array
            ctx.set_field(vh, 3, args.get(3).copied().unwrap_or(Value::Object(None))); // component type
            Ok(Some(Value::Object(Some(vh))))
        });
    r.set_category(__prev_cat);
}

// =============================================================================
// java.util.concurrent.atomic — LongAccumulator, DoubleAccumulator, DoubleAdder
// =============================================================================

pub(crate) fn register_p70_atomic_accumulators(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // LongAccumulator = 3-field (identity=0 Long, current=1 Long, operator=2 ObjectRef)
    let la = "java/util/concurrent/atomic/LongAccumulator";
    r.register(
        la,
        "<init>",
        "(Ljava/util/function/LongBinaryOperator;J)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let identity = match args.get(2) {
                Some(Value::Long(v)) => *v,
                _ => 0,
            };
            ctx.set_field(this, 0, Value::Long(identity));
            ctx.set_field(this, 1, Value::Long(identity));
            // Store the operator reference
            ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Object(None)));
            Ok(None)
        },
    );
    r.register(la, "accumulate", "(J)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let x = match args.get(1) {
            Some(Value::Long(v)) => *v,
            _ => 0,
        };
        let cur = match ctx.get_field(this, 1) {
            Value::Long(v) => v,
            _ => 0,
        };
        // Try to invoke the operator; fallback to addition
        let result = if let Value::Object(Some(op)) = ctx.get_field(this, 2) {
            match ctx.invoke_virtual(
                op,
                "applyAsLong",
                "(JJ)J",
                &[Value::Long(cur), Value::Long(x)],
            ) {
                Ok(Some(Value::Long(r))) => r,
                _ => cur + x, // fallback
            }
        } else {
            cur + x
        };
        ctx.set_field(this, 1, Value::Long(result));
        Ok(None)
    });
    r.register(la, "get", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(la, "longValue", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(la, "intValue", "()I", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let v = match ctx.get_field(this, 1) {
            Value::Long(v) => v as i32,
            _ => 0,
        };
        Ok(Some(Value::Int(v)))
    });
    r.register(la, "floatValue", "()F", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let v = match ctx.get_field(this, 1) {
            Value::Long(v) => v as f32,
            _ => 0.0,
        };
        Ok(Some(Value::Float(v)))
    });
    r.register(la, "doubleValue", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let v = match ctx.get_field(this, 1) {
            Value::Long(v) => v as f64,
            _ => 0.0,
        };
        Ok(Some(Value::Double(v)))
    });
    r.register(la, "reset", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let identity = ctx.get_field(this, 0);
        ctx.set_field(this, 1, identity);
        Ok(None)
    });
    r.register(la, "getThenReset", "()J", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cur = ctx.get_field(this, 1);
        let identity = ctx.get_field(this, 0);
        ctx.set_field(this, 1, identity);
        Ok(Some(cur))
    });

    // DoubleAccumulator = 3-field (identity=0 Double, current=1 Double, operator=2 ObjectRef)
    let da = "java/util/concurrent/atomic/DoubleAccumulator";
    r.register(
        da,
        "<init>",
        "(Ljava/util/function/DoubleBinaryOperator;D)V",
        |ctx, args| {
            let this = obj_arg(args, 0)?;
            let identity = match args.get(2) {
                Some(Value::Double(v)) => *v,
                _ => 0.0,
            };
            ctx.set_field(this, 0, Value::Double(identity));
            ctx.set_field(this, 1, Value::Double(identity));
            ctx.set_field(this, 2, args.get(1).copied().unwrap_or(Value::Object(None)));
            Ok(None)
        },
    );
    r.register(da, "accumulate", "(D)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let x = match args.get(1) {
            Some(Value::Double(v)) => *v,
            _ => 0.0,
        };
        let cur = match ctx.get_field(this, 1) {
            Value::Double(v) => v,
            _ => 0.0,
        };
        let result = if let Value::Object(Some(op)) = ctx.get_field(this, 2) {
            match ctx.invoke_virtual(
                op,
                "applyAsDouble",
                "(DD)D",
                &[Value::Double(cur), Value::Double(x)],
            ) {
                Ok(Some(Value::Double(r))) => r,
                _ => cur + x,
            }
        } else {
            cur + x
        };
        ctx.set_field(this, 1, Value::Double(result));
        Ok(None)
    });
    r.register(da, "get", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(da, "doubleValue", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    r.register(da, "reset", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let identity = ctx.get_field(this, 0);
        ctx.set_field(this, 1, identity);
        Ok(None)
    });

    // DoubleAdder = 1-field (sum=0 Double)
    let dad = "java/util/concurrent/atomic/DoubleAdder";
    r.register(dad, "<init>", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Double(0.0));
        Ok(None)
    });
    r.register(dad, "add", "(D)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let x = match args.get(1) {
            Some(Value::Double(v)) => *v,
            _ => 0.0,
        };
        let cur = match ctx.get_field(this, 0) {
            Value::Double(v) => v,
            _ => 0.0,
        };
        ctx.set_field(this, 0, Value::Double(cur + x));
        Ok(None)
    });
    r.register(dad, "sum", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(dad, "doubleValue", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    r.register(dad, "reset", "()V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, Value::Double(0.0));
        Ok(None)
    });
    r.register(dad, "sumThenReset", "()D", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let cur = ctx.get_field(this, 0);
        ctx.set_field(this, 0, Value::Double(0.0));
        Ok(Some(cur))
    });
    r.set_category(__prev_cat);
}

// =============================================================================
// Misc: java.util.EnumMap, java.util.EnumSet, java.lang.Iterable additions
// =============================================================================

pub(crate) fn register_p70_misc(r: &mut NativeMethodRegistry) {
    let __prev_cat = r.current_category();
    r.set_category(cratonvm_native_api::NativeKind::Bridge);
    // EnumMap and EnumSet core methods already registered in earlier phases — only add NEW methods here

    // EnumSet: complementOf and range (not in earlier phases)
    let es = "java/util/EnumSet";
    r.register(
        es,
        "complementOf",
        "(Ljava/util/EnumSet;)Ljava/util/EnumSet;",
        |ctx, _args| {
            // Use same layout as existing EnumSet: field 0 = ArrayList backing, field 1 = type
            let set = alloc_concurrent_synthetic(ctx, "java/util/EnumSet", 2);
            // Pin across the array/backing allocs below — a moving young GC
            // there would relocate them (native stale-local family).
            let set_pin = ctx.pin_native_root(set);
            let arr = ctx.new_array(cratonvm_types::ArrayElementType::Reference, 0);
            let arr_pin = ctx.pin_native_root(arr);
            let backing = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
            let set = ctx.read_native_pin(set_pin, set);
            let arr = ctx.read_native_pin(arr_pin, arr);
            ctx.set_field(backing, 0, Value::Object(Some(arr)));
            ctx.set_field(backing, 1, Value::Int(0));
            ctx.set_field(set, 0, Value::Object(Some(backing)));
            ctx.set_field(set, 1, Value::Object(None));
            ctx.unpin_native_roots(set_pin);
            Ok(Some(Value::Object(Some(set))))
        },
    );
    r.register(
        es,
        "range",
        "(Ljava/lang/Enum;Ljava/lang/Enum;)Ljava/util/EnumSet;",
        crate::phases_early::native_es_range,
    );

    // java.io.Serializable — marker interface (no methods, but sometimes referenced)
    r.register(
        "java/io/Serializable",
        "serialVersionUID",
        "J",
        |_ctx, _args| Ok(Some(Value::Long(0))),
    );

    // java.lang.Comparable — compareTo for String already exists; add for wrappers
    r.register(
        "java/lang/Comparable",
        "compareTo",
        "(Ljava/lang/Object;)I",
        |_ctx, _args| Ok(Some(Value::Int(0))),
    );

    // java.lang.AutoCloseable
    r.register("java/lang/AutoCloseable", "close", "()V", |_ctx, _args| {
        // AutoCloseable is a marker interface — close() is implemented by concrete classes
        // (FileInputStream, Socket, etc.). This default registration is a fallback for
        // callers that hold a raw AutoCloseable reference; the real implementation runs
        // via virtual dispatch on the concrete subclass.
        Ok(None)
    });
    r.set_category(__prev_cat);
}

// =============================================================================
// Phase 71: Wrapper extras, BigInteger extensions, Files bridge, Thread extras,
//           Zip/compression extras, java.util.logging extras
// =============================================================================

pub(crate) fn register_phase71_natives(registry: &mut NativeMethodRegistry) {
    let __prev_cat = registry.current_category();
    registry.set_category(cratonvm_native_api::NativeKind::Bridge);
    register_p71_wrapper_extras(registry);
    register_p71_biginteger_extras(registry);
    register_p71_files_bridge(registry);
    register_p71_thread_extras(registry);
    crate::uncaught_handlers::register_uncaught_handler_natives(registry);
    register_p71_zip_extras(registry);
    register_p71_logging_extras(registry);
    registry.set_category(__prev_cat);
}

// =============================================================================
// Wrapper utility extras (Integer, Long, Double, Float)
