fn p71_fmt_radix(mut v: u64, radix: u32) -> String {
    if v == 0 {
        return "0".to_string();
    }
    const D: &[u8] = b"0123456789abcdefghijklmnopqrstuvwxyz";
    let mut buf = Vec::new();
    while v > 0 {
        buf.push(D[(v % radix as u64) as usize] as char);
        v /= radix as u64;
    }
    buf.iter().rev().collect()
}

